//! Headless multi-node integration test harness (Step 9B-i).
//!
//! Spins up several real `spawn_node` event loops IN ONE PROCESS, each with its
//! own keypairs and temp SQLCipher DBs, wired through an in-process
//! [`MockRelay`] that mimics only the relay's load-bearing behaviour (room
//! routing plus offline buffering; all crypto, sync and ordering live in the
//! nodes). No sockets, no TLS, no network. Design: `project_multinode_test_harness`.

use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};

use tokio::sync::mpsc;

use crate::crdt::server_state::ServerState;
use crate::crypto::{CryptoStore, OlmManager};
use crate::identity::native_identity::NativeKeypair;
use super::crdt_store::CrdtStore;
use super::types::{CallPresence, NetworkEvent, NodeCommand, ReadMarker};
use super::ws_client::{WsCommand, WsEvent};

/// Process-wide guard: the resolver and the other global statics the nodes touch
/// are process-global, so harness tests run serially from a clean resolver. The
/// guard IS `resolver::test_lock()`, shared with the unit tests, so neither can
/// wipe the other's links mid-assert.
pub(crate) fn test_guard() -> std::sync::MutexGuard<'static, ()> {
    let g = super::resolver::test_lock();
    super::resolver::clear_for_test();
    g
}

// ---------------------------------------------------------------------------
// MockRelay — in-process broker mimicking the production relay's routing.
// ---------------------------------------------------------------------------

/// What a node hands the broker so the broker can deliver events back to it.
struct Conn {
    event_tx: mpsc::UnboundedSender<WsEvent>,
    online: bool,
}

#[derive(Default)]
struct RelayInner {
    /// device_peer_id -> connection (event sink + online flag).
    conns: HashMap<String, Conn>,
    /// room_code -> set of device_peer_ids currently in the room.
    rooms: HashMap<String, HashSet<String>>,
    /// `inbox:{master}` room -> the devices the relay's fold counts as that master's.
    /// Only they see each other and receive there, as on the relay.
    inbox_owners: HashMap<String, HashSet<String>>,
    /// master -> every roster shown for it folded into one, with when the relay first
    /// saw each pending join, as on the relay (`relay-uws/src/roster_book.h`).
    inbox_rosters: HashMap<String, InboxRoster>,
    /// target device_peer_id -> buffered (room, frame-kind, from, data) for
    /// replay when the target next joins that room. Mirrors the relay's
    /// offline buffer (the load-bearing peer-fallback path).
    offline: HashMap<String, Vec<BufferedMsg>>,
    /// (room_code, channel/topic) -> ring of (sender_device, frame data), mirroring
    /// the relay's per-channel topic buffers: key presence means registered, inbound
    /// topic frames tee in, catch-up replays them. Caps and TTL are not modelled.
    topic_buffers: HashMap<(String, String), Vec<(String, Vec<u8>)>>,
    /// Topics nobody subscribes to, as on the relay: a frame only enters the ring.
    unsubscribed_topics: HashSet<String>,
    /// A relay from before the catch-up end mark.
    withhold_catchup_end: bool,
    /// nickname -> (claimer device_peer_id, claimer's self-reported master).
    /// Mirrors the relay's temporary-nickname registry. TTL not modeled;
    /// an offline holder resolves as not_found like the real staleness check.
    nicknames: HashMap<String, (String, String, super::nick_claim::NickClaim)>,
    /// Devices that silently DON'T receive 0x03 room broadcasts while still present
    /// in the room. Models the relay's backpressure drop on a long-lived socket (uWS
    /// returns DROPPED with no error to the sender), the loss mode behind the
    /// join-order MLS epoch race: the victim looks perfectly healthy to everyone.
    broadcast_deaf: HashSet<String>,
    /// (sender, target) pairs whose direct frames the relay swallows: it keeps what
    /// it read (recording still sees it) and delivers nothing.
    swallowed_directs: HashSet<(String, String)>,
    /// (sender, target) pairs whose direct frames the relay holds back, in order,
    /// until the test releases them: a slow link, so two frames can cross.
    held_directs: HashMap<(String, String), Vec<BufferedMsg>>,
    /// (sender, target) pairs whose stream frames (0x02) the relay holds back, in order,
    /// until the test releases or loses them.
    held_streams: HashMap<(String, String), Vec<BufferedMsg>>,
    /// (sender, target) pairs whose 0x03 room broadcasts the relay holds back, in order,
    /// until the test releases them: two devices act before either hears the other.
    held_broadcasts: HashMap<(String, String), Vec<WsEvent>>,
    /// Devices whose outgoing data frames are kept, so a test can replay one
    /// later (a captured older announce is a replay, not a forgery).
    recording: HashSet<String>,
    recorded: Vec<(String, Vec<u8>)>,
    /// device_peer_id -> its keypair, so a test can put a frame on the wire as that
    /// device (sealed with its own key), exactly as the device itself would.
    keys: HashMap<String, NativeKeypair>,
    /// Claimed link codes (their rendezvous part) -> the claiming device. One per
    /// device, consumed by the first resolve, as on the relay; TTL not modelled.
    link_codes: HashMap<String, String>,
    /// (querying device, queried ids) for every `check_peers`: what a node ASKS the
    /// relay, which the reply alone cannot show.
    check_peers_log: Vec<(String, Vec<String>)>,
    /// (sender, room, target) of every channel copy (0x09) the relay would keep for a
    /// member who missed the room's broadcast. Recorded only: the fetch node that reads
    /// them is out of harness scope.
    channel_copies: Vec<(String, String, String)>,
    /// target device id -> the destruction orders parked for it, mirroring the relay's
    /// kill list: one slot per issuer, replaced only by that issuer's NEWER deposit,
    /// all handed over on the device's next auth, each deleted only by the device's
    /// ack naming its issuer and stamp, or by its bare ack.
    kill_list: HashMap<String, Vec<KillEntry>>,
    /// (acking device, the signal it named) for every `kill_ack`, `None` = bare: a
    /// bare ack clears junk and a genuine order alike, so only the record tells them apart.
    kill_acks: Vec<(String, Option<super::ws_client::KillSignalId>)>,
    /// Join lock chains by record key (`join_lock::record_key`), held by the rule the
    /// real relay applies (`join_lock::relay_put`).
    locks: HashMap<String, Vec<super::join_lock::LockLink>>,
    /// device -> the lock reads it asked for, not yet answered ([`MockRelay::hold_lock_reads`]).
    held_lock_reads: HashMap<String, Vec<WsEvent>>,
    /// device -> server room -> the public half of the door its socket proves
    /// (`WsCommand::SetDoor`); the mock compares it where the relay checks a proof.
    doors_held: HashMap<String, HashMap<String, String>>,
    /// Door-locked rooms (`relay-uws/src/door_room.h`): who sees each, `None` for
    /// holding the newest door, `Some` until a lock move's grace ends.
    provers: HashMap<String, HashMap<String, Option<std::time::Instant>>>,
    /// (room, device) pairs a door-locked room keeps showing whatever door they prove:
    /// a room whose lock the relay does not hold (a legacy server, an evicted record).
    kept_in_view: HashSet<(String, String)>,
    door_sweeper: bool,
    /// Everything the relay can read while a test has the tap on (claim C-24).
    tap: Option<Wiretap>,
    /// Optional load meter (scaling benchmark). When `Some`, every command the
    /// relay handles and every frame the relay DELIVERS to a socket is tallied
    /// here — the ground truth for "what does one server operation cost the
    /// relay + the coordinator". `None` in normal tests (zero overhead).
    meter: Option<RelayMeter>,
}

/// Frame accounting for the scaling benchmark, cumulative from the last
/// [`MockRelay::reset_meter`]. `*_cmds` are inbound commands a NODE issued;
/// `deliveries` are outbound frames the RELAY copied to a socket, which is the
/// O(N) fan-out and the true bandwidth bottleneck.
#[derive(Default, Clone, Debug)]
pub(crate) struct RelayMeter {
    /// SendDirect / SendDirectImage commands issued (the per-device targeted
    /// fan-out — MLS commits/welcomes ride this; O(N) on the coordinator).
    pub send_direct_cmds: u64,
    /// SendToRoom commands issued (single-frame broadcast; O(1) sender work).
    pub send_to_room_cmds: u64,
    /// SendToRoomTopic commands issued (single-frame topic broadcast).
    pub send_topic_cmds: u64,
    /// Total outbound frames the relay actually delivered to a socket, across
    /// ALL command types. This IS relay egress — the bottleneck the relay's
    /// 1 Gbps pipe caps. `bytes_out` weights it by payload size.
    pub deliveries: u64,
    pub bytes_out: u64,
    /// Deliveries attributable to broadcast fan-out (SendToRoom + topic), so we
    /// can separate "one post → N copies" egress from targeted-send egress.
    pub broadcast_deliveries: u64,
    /// Deliveries attributable to targeted SendDirect fan-out (commit/welcome).
    pub direct_deliveries: u64,
}

/// What a relay reads: every payload a device hands it, seal stripped, and every
/// room name a device joins.
#[derive(Default, Clone)]
pub(crate) struct Wiretap {
    pub frames: Vec<TapFrame>,
    pub rooms: HashSet<String>,
}

/// One payload as the relay read it, seal stripped.
#[derive(Clone)]
pub(crate) struct TapFrame {
    pub from: String,
    pub room: String,
    /// The device a direct frame names; `None` for a room or topic broadcast.
    pub to: Option<String>,
    /// The ring a topic broadcast rides; `None` for every other frame.
    pub topic: Option<String>,
    pub body: Vec<u8>,
}

impl TapFrame {
    /// The wire `type` of a JSON body, `binary` for anything else.
    pub(crate) fn kind(&self) -> String {
        serde_json::from_slice::<serde_json::Value>(&self.body)
            .ok()
            .and_then(|v| v.get("type").and_then(|t| t.as_str()).map(str::to_string))
            .unwrap_or_else(|| "binary".into())
    }
}

impl Wiretap {
    fn record(&mut self, from: &str, cmd: &WsCommand) {
        let (room, to, topic, data) = match cmd {
            WsCommand::JoinRoom { room_code } | WsCommand::JoinInbox { room_code, .. } => {
                self.rooms.insert(room_code.clone());
                return;
            }
            WsCommand::SendToRoom { room_code, data }
            | WsCommand::SendPublic { room_code, data } => (room_code, None, None, data),
            WsCommand::SendToRoomTopic { room_code, topic, data } => (room_code, None, Some(topic), data),
            WsCommand::SendDirect { room_code, target_peer, data }
            | WsCommand::SendDirectImage { room_code, target_peer, data }
            | WsCommand::SendBinaryDirect { room_code, target_peer, data }
            | WsCommand::SendChannelDirect { room_code, target_peer, data, .. } => (room_code, Some(target_peer), None, data),
            _ => return,
        };
        self.frames.push(TapFrame {
            from: from.to_string(),
            room: room.clone(),
            to: to.cloned(),
            topic: topic.cloned(),
            body: super::frame_auth::unchecked_body(data).to_vec(),
        });
    }

    /// The wire kind of every plaintext frame whose message may ride only inside Olm.
    pub(crate) fn lane_leaks(&self) -> Vec<String> {
        self.frames
            .iter()
            .filter_map(|f| {
                let msg: super::types::HavenMessage = serde_json::from_slice(&f.body).ok()?;
                (msg.lane() != super::types::Lane::Relay)
                    .then(|| format!("{} from {} in {}", msg.wire_kind(), f.from, f.room))
            })
            .collect()
    }

    /// Every frame or room name in which `needle` is readable, as "kind from sender in room".
    pub(crate) fn readable(&self, needle: &str) -> Vec<String> {
        let n = needle.as_bytes();
        let mut hits: Vec<String> = self
            .frames
            .iter()
            .filter(|f| f.body.windows(n.len()).any(|w| w == n))
            .map(|f| format!("{} from {} in {}", f.kind(), f.from, f.room))
            .collect();
        hits.extend(self.rooms.iter().filter(|r| r.contains(needle)).map(|r| format!("room name {r}")));
        hits
    }
}

/// The relay's handling of one `lock_put`, as `relay-uws` does it: the chain it holds
/// afterwards, and whether the submitted newest lock is now its own.
fn relay_lock_put(
    locks: &mut HashMap<String, Vec<super::join_lock::LockLink>>,
    server: &str,
    owner: &str,
    links: &[super::join_lock::LockLink],
) -> (Vec<super::join_lock::LockLink>, bool) {
    let key = super::join_lock::record_key(server, owner);
    let stored = locks.get(&key).cloned().unwrap_or_default();
    let names_owner = links.first().is_none_or(|first| {
        !first.is_base()
            || crate::crdt::anchor::is_genesis_id(server)
            || super::join_lock::base_owner(server, first).as_deref() == Some(owner)
    });
    let Some(next) = names_owner.then(|| super::join_lock::relay_put(server, &stored, links)).flatten() else {
        return (stored, false);
    };
    locks.insert(key, next.clone());
    let accepted = match (next.last(), links.last()) {
        (Some(tip), Some(ours)) => tip.same_lock(ours),
        _ => false,
    };
    (next, accepted)
}

/// The relay's door grace (`door_room::GRACE_MS`, 60 s), short enough for a test to
/// wait out.
const MOCK_DOOR_GRACE: std::time::Duration = std::time::Duration::from_secs(4);

#[derive(Clone)]
struct KillEntry {
    blob: String,
    issued_at_ms: i64,
    issuer: String,
}

impl KillEntry {
    fn signal(&self) -> WsEvent {
        WsEvent::KillSignal {
            blob: self.blob.clone(),
            signal: super::ws_client::KillSignalId { issuer: self.issuer.clone(), issued_at_ms: self.issued_at_ms },
        }
    }
}

struct BufferedMsg {
    room: String,
    from: String,
    data: Vec<u8>,
    /// true => deliver as DirectMessage on replay; false => Message (room bcast).
    direct: bool,
}

fn wall_now_ms() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or_default()
}

/// Shared handle to the in-process relay. Clone-able; all clones point at the
/// same inner state behind a mutex.
#[derive(Clone)]
pub(crate) struct MockRelay {
    inner: Arc<Mutex<RelayInner>>,
}

impl MockRelay {
    /// Knows the key of every `seed_bytes` identity a test can mint, so a frame put on
    /// the wire as one of them is sealed by it, as that peer itself would seal it.
    pub(crate) fn new() -> Self {
        let keys = (0..=u8::MAX)
            .map(|tag| {
                let kp = NativeKeypair::from_secret_bytes(&seed_bytes(tag));
                (kp.peer_id(), kp)
            })
            .collect();
        Self { inner: Arc::new(Mutex::new(RelayInner { keys, ..RelayInner::default() })) }
    }

    /// Register a freshly-spawned node: take ownership of its outbound command
    /// stream (drive it on a background task) and remember its inbound event
    /// sink. Emits `Connected` to the node so it runs its connect flow
    /// (join inbox + friend DM rooms).
    fn register(
        &self,
        peer_id: String,
        mut cmd_rx: mpsc::UnboundedReceiver<WsCommand>,
        event_tx: mpsc::UnboundedSender<WsEvent>,
    ) {
        {
            let mut inner = self.inner.lock().unwrap();
            inner.conns.insert(peer_id.clone(), Conn { event_tx: event_tx.clone(), online: true });
            // The relay's door grace sweep, as its 5 s timer.
            if !inner.door_sweeper {
                inner.door_sweeper = true;
                let weak = Arc::downgrade(&self.inner);
                tokio::spawn(async move {
                    let mut every = tokio::time::interval(std::time::Duration::from_millis(300));
                    loop {
                        every.tick().await;
                        let Some(inner) = weak.upgrade() else { break };
                        inner.lock().unwrap().sweep_doors();
                    }
                });
            }
        }
        let relay = self.clone();
        let pid = peer_id.clone();
        tokio::spawn(async move {
            while let Some(cmd) = cmd_rx.recv().await {
                relay.handle_command(&pid, cmd);
            }
        });
        // Tell the node it's connected (mirrors WsEvent::Connected on real auth).
        let _ = event_tx.send(WsEvent::Connected);
        self.deliver_kill_signal(&peer_id);
    }

    /// A bare socket for `peer_id` with no node behind it: an outsider that sends what it
    /// likes and reads everything the relay hands it.
    pub(crate) fn attach_raw(&self, peer_id: &str) -> (mpsc::UnboundedSender<WsCommand>, mpsc::UnboundedReceiver<WsEvent>) {
        let (cmd_tx, cmd_rx) = mpsc::unbounded_channel();
        let (event_tx, event_rx) = mpsc::unbounded_channel();
        self.register(peer_id.to_string(), cmd_rx, event_tx);
        (cmd_tx, event_rx)
    }

    /// Remember a device's keypair, so injected frames can be sealed as that device.
    pub(crate) fn register_key(&self, device: &NativeKeypair) {
        self.inner.lock().unwrap().keys.insert(device.peer_id(), device.clone());
    }

    /// The relay hands a parked order over immediately after `auth_ok`, before any
    /// join: a device whose identity is gone may never join a room again.
    fn deliver_kill_signal(&self, peer_id: &str) {
        let inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get(peer_id).filter(|c| c.online) {
            for entry in inner.kill_list.get(peer_id).into_iter().flatten() {
                let _ = conn.event_tx.send(entry.signal());
            }
        }
    }

    /// The first order parked for `target`, as `(blob, issued_at_ms, issuer)`. `None`
    /// once the target has acked every one.
    #[allow(dead_code)]
    pub(crate) fn kill_entry(&self, target: &str) -> Option<(String, i64, String)> {
        self.kill_entries(target).into_iter().next()
    }

    /// Every order parked for `target`, as `(blob, issued_at_ms, issuer)`.
    pub(crate) fn kill_entries(&self, target: &str) -> Vec<(String, i64, String)> {
        let inner = self.inner.lock().unwrap();
        inner
            .kill_list
            .get(target)
            .into_iter()
            .flatten()
            .map(|e| (e.blob.clone(), e.issued_at_ms, e.issuer.clone()))
            .collect()
    }

    /// Every `kill_ack` `device` sent, oldest first, as the `(issuer, issued_at_ms)`
    /// it named, `None` for a bare ack.
    pub(crate) fn kill_acks_from(&self, device: &str) -> Vec<Option<(String, i64)>> {
        let inner = self.inner.lock().unwrap();
        inner
            .kill_acks
            .iter()
            .filter(|(from, _)| from == device)
            .map(|(_, s)| s.as_ref().map(|s| (s.issuer.clone(), s.issued_at_ms)))
            .collect()
    }

    /// The join lock chain the relay holds for a server.
    pub(crate) fn lock_chain(&self, server: &str, owner: &str) -> Vec<super::join_lock::LockLink> {
        let inner = self.inner.lock().unwrap();
        inner.locks.get(&super::join_lock::record_key(server, owner)).cloned().unwrap_or_default()
    }

    /// A hostile relay: `links` become the chain it hands out for the server, by no rule.
    pub(crate) fn plant_lock(&self, server: &str, owner: &str, links: Vec<super::join_lock::LockLink>) {
        let mut inner = self.inner.lock().unwrap();
        let before = inner.room_door(server);
        inner.locks.insert(super::join_lock::record_key(server, owner), links);
        if inner.room_door(server).is_some() && inner.room_door(server) != before {
            inner.relock(server, before.is_some());
        }
    }

    /// A relay restart without the memfd snapshot: every join lock chain is gone.
    pub(crate) fn forget_locks(&self) {
        self.inner.lock().unwrap().locks.clear();
    }

    /// A `lock_put` from a client that is not one of the test's nodes (a rogue mod's
    /// modified client), judged by the same rule. Returns whether the relay took it.
    pub(crate) fn put_lock(&self, server: &str, owner: &str, links: &[super::join_lock::LockLink]) -> bool {
        let mut inner = self.inner.lock().unwrap();
        let before = inner.room_door(server);
        let took = relay_lock_put(&mut inner.locks, server, owner, links).1;
        if inner.room_door(server).is_some() && inner.room_door(server) != before {
            inner.relock(server, before.is_some());
        }
        took
    }

    /// Keep `device` seeing `room` through every lock move, as a relay that does not
    /// hold the room's lock does: the door never hides it.
    pub(crate) fn keep_in_view(&self, device: &str, room: &str) {
        self.inner.lock().unwrap().kept_in_view.insert((room.to_string(), device.to_string()));
    }

    /// What a member's socket proves on joining `room`: the newest door the relay holds,
    /// for a bare socket that stands in for a member.
    pub(crate) fn hand_door(&self, device: &str, room: &str) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(door) = inner.room_door(room) {
            inner.doors_held.entry(device.to_string()).or_default().insert(room.to_string(), door);
        }
    }

    /// Whether `device` sees `room` (the relay's roster and broadcasts there).
    pub(crate) fn sees_room(&self, room: &str, device: &str) -> bool {
        let inner = self.inner.lock().unwrap();
        inner.peer_in_room(room, device) && inner.receives(room, device)
    }

    /// Enable the load meter (scaling benchmark). Resets counts to zero. After
    /// this, every command + delivery is tallied until [`Self::take_meter`].
    pub(crate) fn reset_meter(&self) {
        let mut inner = self.inner.lock().unwrap();
        inner.meter = Some(RelayMeter::default());
    }

    /// Snapshot the current meter (leaves it running). `None` if never enabled.
    pub(crate) fn meter(&self) -> Option<RelayMeter> {
        self.inner.lock().unwrap().meter.clone()
    }

    /// The DEVICE peer_ids the relay considers online. This is the relay's
    /// authoritative presence view, the same thing the real relay reports via
    /// `RoomMembers`, so inspectors read presence from here and never from a node.
    pub(crate) fn online_devices(&self) -> std::collections::HashSet<String> {
        let inner = self.inner.lock().unwrap();
        inner
            .conns
            .iter()
            .filter(|(_, c)| c.online)
            .map(|(id, _)| id.clone())
            .collect()
    }

    /// DEVICE peer_ids currently present in `room` (online + joined). Mirrors the
    /// relay's per-room membership set. Raw-layer presence for future scenarios
    /// (e.g. asserting which of a member's devices are in a server room).
    #[allow(dead_code)]
    pub(crate) fn room_devices(&self, room: &str) -> std::collections::HashSet<String> {
        let inner = self.inner.lock().unwrap();
        inner.rooms.get(room).cloned().unwrap_or_default()
    }

    /// The devices that own `master`'s inbox.
    pub(crate) fn inbox_owners(&self, master: &str) -> std::collections::HashSet<String> {
        let inner = self.inner.lock().unwrap();
        inner.inbox_owners.get(&format!("inbox:{master}")).cloned().unwrap_or_default()
    }

    /// The recovery key the relay pinned for `master`, empty while it holds none.
    pub(crate) fn inbox_recovery_key(&self, master: &str) -> String {
        let inner = self.inner.lock().unwrap();
        inner.inbox_rosters.get(master).map(|held| held.roster.r_pub.clone()).unwrap_or_default()
    }

    /// Move the relay's first sight of `device`'s pending join for `master` back by
    /// `by_ms`, as if that much time had passed at the relay.
    pub(crate) fn age_inbox_wait(&self, master: &str, device: &str, by_ms: i64) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(held) = inner.inbox_rosters.get_mut(master) {
            let key = format!("{}|{device}", held.roster.base());
            if let Some(seen) = held.seen.get_mut(&key) {
                *seen -= by_ms;
            }
        }
    }

    /// Frames currently buffered for `peer`. The relay buffers a direct frame under
    /// the TARGET device id when that device is not in the room and (on the real
    /// relay) pushes to it, so a non-zero count is the proxy for "would be woken".
    #[allow(dead_code)]
    pub(crate) fn buffered_count(&self, peer: &str) -> usize {
        let inner = self.inner.lock().unwrap();
        inner.offline.get(peer).map(|v| v.len()).unwrap_or(0)
    }

    /// The buffered payloads held for `peer`, CLONED (nothing is consumed).
    /// `buffered_count` answers "was anything left for them"; this answers
    /// "WHAT was left", which is the only way to assert that the frame waiting
    /// in a mailbox is the decline and that it names the right request.
    #[allow(dead_code)]
    pub(crate) fn buffered_frames(&self, target: &str) -> Vec<Vec<u8>> {
        let inner = self.inner.lock().unwrap();
        inner
            .offline
            .get(target)
            .map(|v| v.iter().map(|m| super::frame_auth::unchecked_body(&m.data).to_vec()).collect())
            .unwrap_or_default()
    }

    /// Drop everything buffered for `target`, simulating the mailbox TTL lapsing
    /// (the real relay holds a master's inbox for 3 days). The case that matters
    /// is a decline that expires BEFORE the requester next boots: the requester
    /// then re-deposits its request, and the decliner has to answer again.
    #[allow(dead_code)]
    pub(crate) fn expire_mailbox(&self, target: &str) {
        let mut inner = self.inner.lock().unwrap();
        inner.offline.remove(target);
    }

    /// Test-only: deliver a raw frame to `target` as if `from` had sent it in
    /// `room`, bypassing the sender's own node logic — simulates a hostile or
    /// buggy peer pushing an UNSOLICITED protocol message (the real relay
    /// forwards any authed frame; sender honesty is not a transport guarantee).
    #[allow(dead_code)]
    pub(crate) fn inject_direct(&self, room: &str, from: &str, target: &str, data: Vec<u8>) {
        let inner = self.inner.lock().unwrap();
        let data = inner.sealed_as(from, room, target, data);
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::DirectMessage {
                room: room.to_string(),
                from: from.to_string(),
                data,
            });
        }
    }

    /// Deliver `data` to `target` as a direct frame stamped `from`, byte for byte: what a
    /// relay can do with no key at all (an unsealed frame, or one sealed by someone else).
    #[allow(dead_code)]
    pub(crate) fn inject_raw_direct(&self, room: &str, from: &str, target: &str, data: Vec<u8>) {
        let inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::DirectMessage {
                room: room.to_string(),
                from: from.to_string(),
                data,
            });
        }
    }

    /// Tell `target` that `peer` joined `room`, with no join behind it: an event that
    /// queues in order behind every frame already delivered.
    pub(crate) fn inject_presence(&self, target: &str, room: &str, peer: &str) {
        let inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::PeerJoined { room: room.to_string(), peer_id: peer.to_string() });
        }
    }

    /// [`Self::inject_raw_direct`] delivered as a room broadcast.
    #[allow(dead_code)]
    pub(crate) fn inject_raw(&self, room: &str, from: &str, target: &str, data: Vec<u8>) {
        let inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::Message {
                room: room.to_string(),
                from: from.to_string(),
                data,
            });
        }
    }

    /// [`Self::inject_direct`] for a binary stream frame (`WsEvent::BinaryDirect`).
    #[allow(dead_code)]
    pub(crate) fn inject_binary(&self, room: &str, from: &str, target: &str, data: Vec<u8>) {
        let inner = self.inner.lock().unwrap();
        let data = inner.sealed_as(from, room, target, data);
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::BinaryDirect {
                room: room.to_string(),
                from: from.to_string(),
                data,
            });
        }
    }

    /// Mark a node offline (simulate a disconnect): stop delivering to it, drop
    /// it from every room (broadcasting PeerLeft), so peers see it leave. Its
    /// event loop keeps running but receives nothing until it comes back.
    fn set_online(&self, peer_id: &str, online: bool) {
        self.set_online_inner(peer_id, online, true)
    }

    /// A socket that dies WITHOUT the other members being told.
    ///
    /// The real relay only broadcasts `PeerLeft` for a clean leave, so a pulled
    /// adapter leaves peers holding the dead node in `synced_peers`: on its return
    /// their `is_new` guard reads false and the whole reconnect cascade is skipped.
    /// `set_online(false)` is the polite version and cannot reproduce that.
    fn drop_socket_silently(&self, peer_id: &str) {
        self.set_online_inner(peer_id, false, false)
    }

    fn set_online_inner(&self, peer_id: &str, online: bool, announce_leave: bool) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get_mut(peer_id) {
            conn.online = online;
        }
        if !online {
            let rooms: Vec<String> = inner.rooms.keys().cloned().collect();
            for room in rooms {
                let visible = inner.receives(&room, peer_id);
                let was_present = inner
                    .rooms
                    .get_mut(&room)
                    .map(|s| s.remove(peer_id))
                    .unwrap_or(false);
                if let Some(owners) = inner.inbox_owners.get_mut(&room) {
                    owners.remove(peer_id);
                }
                if let Some(provers) = inner.provers.get_mut(&room) {
                    provers.remove(peer_id);
                }
                if was_present && announce_leave && visible {
                    inner.broadcast_except(&room, peer_id, WsEvent::PeerLeft {
                        room: room.clone(),
                        peer_id: peer_id.to_string(),
                    });
                }
            }
            // Tell the offline node its OWN socket died. Without `WsEvent::SessionLost` the
            // node never clears sync-gating state (`synced_peers`, `key_request_in_flight`,
            // ...), so on reconnect the `is_new` guard suppresses the proactive sync and key
            // exchange and the reconnect flow silently does nothing.
            if let Some(conn) = inner.conns.get(peer_id) {
                let _ = conn.event_tx.send(WsEvent::SessionLost);
            }
        } else {
            // Coming back online: re-emit Connected so the node re-runs its
            // join flow (inbox + friend DM rooms) from scratch.
            if let Some(conn) = inner.conns.get(peer_id) {
                let _ = conn.event_tx.send(WsEvent::Connected);
            }
            if let Some(conn) = inner.conns.get(peer_id) {
                for entry in inner.kill_list.get(peer_id).into_iter().flatten() {
                    let _ = conn.event_tx.send(entry.signal());
                }
            }
        }
    }

    /// The relay names `forwarder` as the media forwarder it runs, to `target`.
    pub(crate) fn advertise_forwarder(&self, target: &str, forwarder: &str) {
        let inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get(target) {
            let _ = conn.event_tx.send(WsEvent::MediaForwarderInfo { peer_id: forwarder.to_string(), online: true });
        }
    }

    /// A hostile relay: `nickname` now resolves to `device`, naming `master` with `claim`.
    pub(crate) fn plant_nickname(&self, nickname: &str, device: &str, master: &str, claim: super::nick_claim::NickClaim) {
        self.inner.lock().unwrap().nicknames.insert(nickname.to_string(), (device.to_string(), master.to_string(), claim));
    }

    /// Test inspector: the master a claimed nickname names (None = nickname unknown).
    pub(crate) fn nickname_master(&self, nickname: &str) -> Option<String> {
        let inner = self.inner.lock().unwrap();
        inner.nicknames.get(nickname).map(|v| v.1.clone())
    }

    /// Every frame currently sitting in a (room, topic) ring, oldest first, as
    /// `(sender_device, payload)`. This is the relay-side truth behind a parked
    /// join: the request the joiner deposited, and the members' resolutions.
    /// Nothing is consumed.
    #[allow(dead_code)]
    pub(crate) fn topic_frames(&self, room: &str, topic: &str) -> Vec<(String, Vec<u8>)> {
        let inner = self.inner.lock().unwrap();
        inner
            .topic_buffers
            .get(&(room.to_string(), topic.to_string()))
            .map(|ring| {
                ring.iter()
                    .map(|(from, data)| (from.clone(), super::frame_auth::unchecked_body(data).to_vec()))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Whether a (room, topic) ring has been REGISTERED (`set_topic_buffer`).
    /// An unregistered ring silently drops every publish, exactly like the real
    /// relay, so "the members registered it while they were here" is a real
    /// precondition of a parked join and a real thing to wait for.
    #[allow(dead_code)]
    pub(crate) fn topic_registered(&self, room: &str, topic: &str) -> bool {
        let inner = self.inner.lock().unwrap();
        inner.topic_buffers.contains_key(&(room.to_string(), topic.to_string()))
    }

    /// Test-only: write a frame straight into a (room, topic) ring as if `from` had
    /// published it, creating the ring if the room never registered one.
    ///
    /// Registration is deliberately bypassed, because this models a HOSTILE
    /// publisher: the RECEIVER must refuse the frame on its own merits.
    #[allow(dead_code)]
    pub(crate) fn inject_topic(&self, room: &str, topic: &str, from: &str, data: Vec<u8>) {
        let mut inner = self.inner.lock().unwrap();
        let data = inner.sealed_as(from, room, super::frame_auth::ROUTE_ROOM, data);
        inner
            .topic_buffers
            .entry((room.to_string(), topic.to_string()))
            .or_default()
            .push((from.to_string(), data));
    }

    /// The senders of every channel copy the relay kept for `target`, oldest first.
    pub(crate) fn channel_copies_for(&self, target: &str) -> Vec<String> {
        let inner = self.inner.lock().unwrap();
        inner.channel_copies.iter().filter(|(_, _, t)| t == target).map(|(from, _, _)| from.clone()).collect()
    }

    /// Frames on `topic` only enter its ring, as on the relay for a topic nobody
    /// subscribes to (the join ring).
    pub(crate) fn set_unsubscribed_topic(&self, topic: &str) {
        self.inner.lock().unwrap().unsubscribed_topics.insert(topic.to_string());
    }

    /// A relay that never marks the end of a catch-up.
    pub(crate) fn withhold_catchup_end(&self) {
        self.inner.lock().unwrap().withhold_catchup_end = true;
    }

    /// Lose every frame `from` wrote into a ring: evicted, or never written.
    pub(crate) fn drop_topic_frames_from(&self, room: &str, topic: &str, from: &str) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(ring) = inner.topic_buffers.get_mut(&(room.to_string(), topic.to_string())) {
            ring.retain(|(sender, _)| sender != from);
        }
    }

    /// Every `check_peers` query `from` sent, oldest first.
    pub(crate) fn check_peers_queries(&self, from: &str) -> Vec<Vec<String>> {
        let inner = self.inner.lock().unwrap();
        inner
            .check_peers_log
            .iter()
            .filter(|(f, _)| f == from)
            .map(|(_, q)| q.clone())
            .collect()
    }

    /// A device back online at the relay that has NOT re-joined any room, the one
    /// state a liveness query exists to detect.
    pub(crate) fn mark_online_silently(&self, peer_id: &str) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(conn) = inner.conns.get_mut(peer_id) {
            conn.online = true;
        }
    }

    /// Start reading everything, as a relay can (see [`Wiretap`]).
    pub(crate) fn start_wiretap(&self) {
        self.inner.lock().unwrap().tap = Some(Wiretap::default());
    }

    /// What the tap has read so far.
    pub(crate) fn wiretap(&self) -> Wiretap {
        self.inner.lock().unwrap().tap.clone().unwrap_or_default()
    }

    /// Keep a copy of every data frame this device sends.
    pub(crate) fn set_recording(&self, peer_id: &str, on: bool) {
        let mut inner = self.inner.lock().unwrap();
        if on {
            inner.recording.insert(peer_id.to_string());
        } else {
            inner.recording.remove(peer_id);
        }
    }

    /// The frames recorded from `peer_id`, oldest first.
    pub(crate) fn recorded_frames(&self, peer_id: &str) -> Vec<Vec<u8>> {
        let inner = self.inner.lock().unwrap();
        inner
            .recorded
            .iter()
            .filter(|(from, _)| from == peer_id)
            .map(|(_, data)| data.clone())
            .collect()
    }

    /// Deliver `data` to `target` as if `from` had just sent it into `room`.
    /// A replay: the bytes are whatever the test captured, unchanged.
    pub(crate) fn inject(&self, room: &str, from: &str, target: &str, data: Vec<u8>) {
        let inner = self.inner.lock().unwrap();
        let data = inner.sealed_as(from, room, super::frame_auth::ROUTE_ROOM, data);
        if let Some(conn) = inner.conns.get(target).filter(|c| c.online) {
            let _ = conn.event_tx.send(WsEvent::Message {
                room: room.to_string(),
                from: from.to_string(),
                data,
            });
        }
    }

    /// Make the relay swallow every direct frame from one device to another.
    pub(crate) fn swallow_direct(&self, from: &str, target: &str) {
        self.inner.lock().unwrap().swallowed_directs.insert((from.to_string(), target.to_string()));
    }

    /// Undo [`Self::swallow_direct`].
    pub(crate) fn release_direct(&self, from: &str, target: &str) {
        self.inner.lock().unwrap().swallowed_directs.remove(&(from.to_string(), target.to_string()));
    }

    /// Leave the lock reads `device` asks for unanswered until [`Self::release_lock_reads`]:
    /// a relay slow to answer.
    pub(crate) fn hold_lock_reads(&self, device: &str) {
        self.inner.lock().unwrap().held_lock_reads.entry(device.to_string()).or_default();
    }

    /// How many lock reads from `device` wait unanswered.
    pub(crate) fn held_lock_reads(&self, device: &str) -> usize {
        self.inner.lock().unwrap().held_lock_reads.get(device).map_or(0, Vec::len)
    }

    /// Answer, in order, the lock reads `device` asked for, and stop holding them.
    pub(crate) fn release_lock_reads(&self, device: &str) {
        let mut inner = self.inner.lock().unwrap();
        let held = inner.held_lock_reads.remove(device).unwrap_or_default();
        if let Some(conn) = inner.conns.get(device) {
            for read in held {
                let _ = conn.event_tx.send(read);
            }
        }
    }

    /// Hold back every direct frame from one device to another until [`Self::release_held`].
    pub(crate) fn hold_direct(&self, from: &str, target: &str) {
        self.inner.lock().unwrap().held_directs.entry((from.to_string(), target.to_string())).or_default();
    }

    /// The wire kind of each frame held from `from` to `target`, oldest first.
    pub(crate) fn held_kinds(&self, from: &str, target: &str) -> Vec<String> {
        let inner = self.inner.lock().unwrap();
        inner
            .held_directs
            .get(&(from.to_string(), target.to_string()))
            .map(|held| {
                held.iter()
                    .map(|m| TapFrame {
                        from: m.from.clone(),
                        room: m.room.clone(),
                        to: None,
                        topic: None,
                        body: super::frame_auth::unchecked_body(&m.data).to_vec(),
                    }
                    .kind())
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Deliver, in order, the held frames of one wire kind, and keep holding the rest.
    pub(crate) fn release_held_kind(&self, from: &str, target: &str, kind: &str) {
        let mut inner = self.inner.lock().unwrap();
        let key = (from.to_string(), target.to_string());
        let held = inner.held_directs.remove(&key).unwrap_or_default();
        let (go, stay): (Vec<_>, Vec<_>) = held.into_iter().partition(|m| {
            TapFrame { from: m.from.clone(), room: m.room.clone(), to: None, topic: None, body: super::frame_auth::unchecked_body(&m.data).to_vec() }
                .kind() == kind
        });
        for m in go {
            inner.deliver_direct(&m.room, &m.from, target, m.data, m.direct);
        }
        inner.held_directs.insert(key, stay);
    }

    /// Lose the held frames of one wire kind, and keep holding the rest.
    pub(crate) fn discard_held_kind(&self, from: &str, target: &str, kind: &str) {
        let mut inner = self.inner.lock().unwrap();
        if let Some(held) = inner.held_directs.get_mut(&(from.to_string(), target.to_string())) {
            held.retain(|m| {
                TapFrame { from: m.from.clone(), room: m.room.clone(), to: None, topic: None, body: super::frame_auth::unchecked_body(&m.data).to_vec() }
                    .kind() != kind
            });
        }
    }

    /// Deliver, in order, what [`Self::hold_direct`] kept, and stop holding.
    pub(crate) fn release_held(&self, from: &str, target: &str) {
        let mut inner = self.inner.lock().unwrap();
        let held = inner.held_directs.remove(&(from.to_string(), target.to_string())).unwrap_or_default();
        for m in held {
            inner.deliver_direct(&m.room, &m.from, target, m.data, m.direct);
        }
    }

    /// Hold back every stream frame from one device to another.
    pub(crate) fn hold_streams(&self, from: &str, target: &str) {
        self.inner.lock().unwrap().held_streams.entry((from.to_string(), target.to_string())).or_default();
    }

    /// How many stream frames the relay holds from `from` to `target`.
    pub(crate) fn held_stream_count(&self, from: &str, target: &str) -> usize {
        self.inner.lock().unwrap().held_streams.get(&(from.to_string(), target.to_string())).map_or(0, Vec::len)
    }

    /// Deliver, in order, the stream frames held from `from` to `target` (all of them, or
    /// lose them when `deliver` is false), and stop holding.
    pub(crate) fn release_streams(&self, from: &str, target: &str, deliver: bool) {
        let mut inner = self.inner.lock().unwrap();
        let held = inner.held_streams.remove(&(from.to_string(), target.to_string())).unwrap_or_default();
        if let Some(conn) = inner.conns.get(target).filter(|c| c.online && deliver) {
            for m in held {
                let _ = conn.event_tx.send(WsEvent::BinaryDirect { room: m.room, from: m.from, data: m.data });
            }
        }
    }

    /// Deliver the stream frames held from each of `froms` to `target` one frame from
    /// each in turn, so their streams are open at once, and stop holding.
    pub(crate) fn release_streams_interleaved(&self, froms: &[&str], target: &str) {
        let mut inner = self.inner.lock().unwrap();
        let mut queues: Vec<std::collections::VecDeque<BufferedMsg>> = froms
            .iter()
            .map(|from| inner.held_streams.remove(&(from.to_string(), target.to_string())).unwrap_or_default().into())
            .collect();
        let Some(conn) = inner.conns.get(target).filter(|c| c.online) else { return };
        while queues.iter().any(|q| !q.is_empty()) {
            for m in queues.iter_mut().filter_map(|q| q.pop_front()) {
                let _ = conn.event_tx.send(WsEvent::BinaryDirect { room: m.room, from: m.from, data: m.data });
            }
        }
    }

    /// Hold back every 0x03 room broadcast from one device to another until
    /// [`Self::release_broadcasts`].
    pub(crate) fn hold_broadcasts(&self, from: &str, target: &str) {
        self.inner.lock().unwrap().held_broadcasts.entry((from.to_string(), target.to_string())).or_default();
    }

    /// Deliver, in order, what [`Self::hold_broadcasts`] kept, and stop holding.
    pub(crate) fn release_broadcasts(&self, from: &str, target: &str) {
        let mut inner = self.inner.lock().unwrap();
        let held = inner.held_broadcasts.remove(&(from.to_string(), target.to_string())).unwrap_or_default();
        if let Some(conn) = inner.conns.get(target).filter(|c| c.online) {
            for event in held {
                let _ = conn.event_tx.send(event);
            }
        }
    }

    pub(crate) fn set_broadcast_deaf(&self, peer_id: &str, deaf: bool) {
        let mut inner = self.inner.lock().unwrap();
        if deaf {
            inner.broadcast_deaf.insert(peer_id.to_string());
        } else {
            inner.broadcast_deaf.remove(peer_id);
        }
    }

    fn handle_command(&self, from: &str, cmd: WsCommand) {
        let mut inner = self.inner.lock().unwrap();
        // A door stays with ws_client across a dead socket; the next join proves it.
        if let WsCommand::SetDoor { room_code, door: d } = &cmd
            && !inner.conns.get(from).map(|c| c.online).unwrap_or(false)
        {
            let held = inner.doors_held.entry(from.to_string()).or_default();
            match d {
                Some(d) => held.insert(room_code.clone(), super::sealed_box::key_to_text(&super::sealed_box::public_of(&d.0))),
                None => held.remove(room_code),
            };
            return;
        }
        // Drop everything from an offline node (mirrors a dead socket).
        if !inner.conns.get(from).map(|c| c.online).unwrap_or(false) {
            return;
        }
        if let Some(tap) = inner.tap.as_mut() {
            tap.record(from, &cmd);
        }
        match cmd {
            WsCommand::JoinRoom { room_code } => {
                inner.join(from, &room_code, false);
            }
            WsCommand::JoinInbox { room_code, roster } => {
                // A shown roster decides on its own, so a socket the fold no longer
                // counts loses the inbox here even if it owned it before.
                let owner_ok = inner.show_roster(from, &room_code, roster);
                if !owner_ok && let Some(owners) = inner.inbox_owners.get_mut(&room_code) {
                    owners.remove(from);
                }
                inner.join(from, &room_code, owner_ok);
                if let Some(master) = room_code.strip_prefix("inbox:").filter(|_| owner_ok) {
                    let master = master.to_string();
                    inner.replay_mailbox(from, &master);
                }
            }
            WsCommand::SetDoor { room_code, door } => {
                // What ws_client does with it: prove it on every join, and join a room
                // it is in again at once when the door changed.
                let public = door.map(|d| super::sealed_box::key_to_text(&super::sealed_box::public_of(&d.0)));
                let held = inner.doors_held.entry(from.to_string()).or_default();
                let changed = match &public {
                    Some(p) => held.insert(room_code.clone(), p.clone()).as_ref() != Some(p),
                    None => held.remove(&room_code).is_some(),
                };
                if changed && public.is_some() && inner.peer_in_room(&room_code, from) {
                    inner.join(from, &room_code, false);
                }
            }
            WsCommand::LeaveRoom { room_code } => {
                let visible = inner.receives(&room_code, from);
                let was = inner
                    .rooms
                    .get_mut(&room_code)
                    .map(|s| s.remove(from))
                    .unwrap_or(false);
                if let Some(owners) = inner.inbox_owners.get_mut(&room_code) {
                    owners.remove(from);
                }
                if let Some(provers) = inner.provers.get_mut(&room_code) {
                    provers.remove(from);
                }
                if was && visible {
                    inner.broadcast_except(&room_code, from, WsEvent::PeerLeft {
                        room: room_code.clone(),
                        peer_id: from.to_string(),
                    });
                }
                // Mirror the real ws_client's local leave confirmation (mock
                // nodes bypass ws_client entirely) — the swarm purges the
                // room's peer snapshot on this, closing the stale-room
                // targeted-send blackhole.
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::LeftRoom {
                        room: room_code.clone(),
                    });
                }
            }
            WsCommand::SendToRoom { room_code, data } => {
                if let Some(m) = inner.meter.as_mut() { m.send_to_room_cmds += 1; }
                let data = inner.on_the_wire(from, &room_code, super::frame_auth::ROUTE_ROOM, data);
                let n = data.len() as u64;
                let delivered = inner.broadcast_data_except(&room_code, from, WsEvent::Message {
                    room: room_code.clone(),
                    from: from.to_string(),
                    data,
                });
                if let Some(m) = inner.meter.as_mut() {
                    m.deliveries += delivered;
                    m.broadcast_deliveries += delivered;
                    m.bytes_out += delivered * n;
                }
            }
            WsCommand::SendPublic { room_code, data } => {
                // 0x0A: a prover's public frame reaches everyone a locked room hides too.
                let data = inner.on_the_wire(from, &room_code, super::frame_auth::ROUTE_ROOM, data);
                let to_all = inner.room_door(&room_code).is_some() && inner.receives(&room_code, from);
                let members: Vec<String> = inner.rooms.get(&room_code).map(|s| s.iter().cloned().collect()).unwrap_or_default();
                for m in members {
                    if m == from || inner.broadcast_deaf.contains(&m) || !(to_all || inner.shares(&room_code, &m, from)) {
                        continue;
                    }
                    if let Some(conn) = inner.conns.get(&m).filter(|c| c.online) {
                        let _ = conn.event_tx.send(WsEvent::Message {
                            room: room_code.clone(),
                            from: from.to_string(),
                            data: data.clone(),
                        });
                    }
                }
            }
            WsCommand::SendDirect { room_code, target_peer, data }
            | WsCommand::SendDirectImage { room_code, target_peer, data } => {
                if let Some(m) = inner.meter.as_mut() { m.send_direct_cmds += 1; }
                let data = inner.on_the_wire(from, &room_code, &target_peer, data);
                let n = data.len() as u64;
                let delivered = inner.deliver_direct(&room_code, from, &target_peer, data, true);
                if let Some(m) = inner.meter.as_mut() {
                    m.deliveries += delivered;
                    m.direct_deliveries += delivered;
                    m.bytes_out += delivered * n;
                }
            }
            WsCommand::SendBinaryDirect { room_code, target_peer, data } => {
                // Delivered as BinaryDirect when present, not buffered. Both ends must be in the
                // room: the relay drops a 0x02 whose SENDER never joined, so a sender that skips
                // the join must fail here too rather than passing only under the mock.
                let sender_in_room = inner.peer_in_room(&room_code, from);
                let in_room = inner.peer_in_room(&room_code, &target_peer);
                if !sender_in_room || !RelayInner::paired(&room_code, from, &target_peer) { return; }
                if let Some(held) = inner.held_streams.get_mut(&(from.to_string(), target_peer.clone())) {
                    held.push(BufferedMsg { room: room_code, from: from.to_string(), data, direct: true });
                    return;
                }
                if let Some(conn) = inner.conns.get(&target_peer).filter(|c| c.online && in_room) {
                    let _ = conn.event_tx.send(WsEvent::BinaryDirect {
                        room: room_code,
                        from: from.to_string(),
                        data,
                    });
                }
            }
            WsCommand::SendToRoomTopic { room_code, topic, data } => {
                let data = inner.on_the_wire(from, &room_code, super::frame_auth::ROUTE_ROOM, data);
                // Tee into the channel's ring buffer when registered (relay
                // offline catch-up), mirroring the real relay.
                let key = (room_code.clone(), topic.clone());
                if let Some(buf) = inner.topic_buffers.get_mut(&key) {
                    buf.push((from.to_string(), data.clone()));
                }
                if inner.unsubscribed_topics.contains(&topic) {
                    return;
                }
                if let Some(m) = inner.meter.as_mut() { m.send_topic_cmds += 1; }
                let n = data.len() as u64;
                // Simplify topic routing to a plain room broadcast (no test
                // exercises topic filtering yet).
                let delivered = inner.broadcast_except(&room_code, from, WsEvent::Message {
                    room: room_code.clone(),
                    from: from.to_string(),
                    data,
                });
                if let Some(m) = inner.meter.as_mut() {
                    m.deliveries += delivered;
                    m.broadcast_deliveries += delivered;
                    m.bytes_out += delivered * n;
                }
            }
            WsCommand::SetTopicBuffer { room_code, channels, retention_secs, clear, auth } => {
                // The relay as 0.12 runs it (ring_auth.h): only a control signed by the
                // change key of the newest lock it holds makes or stops rings; an
                // unsigned one only keeps existing rings from idling out, which the mock
                // does not model.
                let Some(auth) = auth else { return };
                if !inner.peer_in_room(&room_code, from) {
                    return;
                }
                let chain = inner
                    .locks
                    .get(&super::join_lock::record_key(&room_code, &auth.owner))
                    .cloned()
                    .unwrap_or_default();
                let now_ms = wall_now_ms();
                if !super::ring_auth::relay_accepts(&room_code, &auth, retention_secs, clear, &channels, &chain, now_ms) {
                    return;
                }
                if clear {
                    let prefix = super::ring_auth::ring_topic(&room_code, Some(&auth.owner), "");
                    inner.topic_buffers.retain(|(r, t), _| r != &room_code || !t.starts_with(&prefix));
                } else {
                    for c in channels {
                        inner.topic_buffers.entry((room_code.clone(), c)).or_default();
                    }
                }
            }
            WsCommand::TopicCatchup { room_code, channel_id, end, .. } => {
                // A ring names who wrote what, when: only for those who see the room.
                if !inner.peer_in_room(&room_code, from) || !inner.receives(&room_code, from) {
                    return;
                }
                // max_age_secs ignored — the mock doesn't model frame age.
                let frames: Vec<(String, Vec<u8>)> = inner
                    .topic_buffers
                    .get(&(room_code.clone(), channel_id.clone()))
                    .map(|v| v.iter().filter(|(s, _)| s != from).cloned().collect())
                    .unwrap_or_default();
                if let Some(conn) = inner.conns.get(from).filter(|c| c.online) {
                    for (sender, data) in frames {
                        let _ = conn.event_tx.send(WsEvent::Message {
                            room: room_code.clone(),
                            from: sender,
                            data,
                        });
                    }
                    if end && !inner.withhold_catchup_end {
                        let _ = conn.event_tx.send(WsEvent::TopicCatchupDone { room: room_code, channel: channel_id });
                    }
                }
            }
            WsCommand::DiscoverPeers { room_code } => {
                // Members only, like the relay — discovery is not a roster dump
                // for any room code you happen to know. In an inbox, owners only.
                let peers: Vec<String> = inner
                    .rooms
                    .get(&room_code)
                    .filter(|s| s.contains(from) && inner.receives(&room_code, from))
                    .map(|s| {
                        s.iter()
                            .filter(|p| *p != from && inner.shares(&room_code, p, from))
                            .cloned()
                            .collect()
                    })
                    .unwrap_or_default();
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::DiscoveredPeers { room: room_code, peers });
                }
            }
            WsCommand::CheckPeers { peers, rooms } => {
                inner.check_peers_log.push((from.to_string(), peers.clone()));
                let online: Vec<String> = peers
                    .into_iter()
                    .filter(|p| inner.conns.get(p).map(|c| c.online).unwrap_or(false))
                    .collect();
                // The relay no longer answers the room-activity probe (it let
                // anyone holding two peer_ids test whether their deterministic
                // DM room was live), so nothing may depend on a reply here.
                let _ = rooms;
                let active_rooms: Vec<String> = Vec::new();
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::PeerStatus { online, active_rooms });
                }
            }
            WsCommand::ClaimNickname { nickname, master, claim } => {
                // The relay takes only a claim the named master signed for this socket.
                if super::nick_claim::verified_master(&nickname, from, &master, &claim, super::types::now_ms()).is_none() {
                    if let Some(conn) = inner.conns.get(from) {
                        let _ = conn.event_tx.send(WsEvent::NicknameError { error: "invalid_claim".to_string(), nickname });
                    }
                    return;
                }
                // Auto-release any old binding of this claimer (like the relay).
                inner.nicknames.retain(|_, v| v.0 != from);
                inner.nicknames.insert(nickname.clone(), (from.to_string(), master, claim));
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::NicknameClaimed { nickname });
                }
            }
            WsCommand::ReleaseNickname => {
                inner.nicknames.retain(|_, v| v.0 != from);
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::NicknameReleased);
                }
            }
            WsCommand::ResolveNickname { nickname } => {
                // An offline holder resolves as not_found (the real relay's
                // dead-holder staleness check).
                let hit = inner.nicknames.get(&nickname).and_then(|(dev, master, claim)| {
                    let online =
                        inner.conns.get(dev).map(|c| c.online).unwrap_or(false);
                    online.then(|| (dev.clone(), master.clone(), claim.clone()))
                });
                let ev = match hit {
                    Some((dev, master, claim)) => WsEvent::NicknameResolved {
                        nickname,
                        peer_id: dev,
                        master_id: master,
                        claim,
                    },
                    None => WsEvent::NicknameError {
                        error: "not_found".to_string(),
                        nickname,
                    },
                };
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(ev);
                }
            }
            WsCommand::KillDeposit { targets, issued_at_ms, blob } => {
                // Relay semantics: at most 16 targets, one slot per issuer that only
                // the same issuer's strictly NEWER deposit replaces, and a connected
                // target is handed it at once (its socket has already authed, so it
                // gets no second auth_ok).
                for target in targets.into_iter().take(16) {
                    let slots = inner.kill_list.entry(target.clone()).or_default();
                    if slots.iter().any(|e| e.issuer == from && issued_at_ms <= e.issued_at_ms) {
                        continue;
                    }
                    slots.retain(|e| e.issuer != from);
                    let entry = KillEntry { blob: blob.clone(), issued_at_ms, issuer: from.to_string() };
                    let signal = entry.signal();
                    slots.push(entry);
                    if let Some(conn) = inner.conns.get(&target).filter(|c| c.online) {
                        let _ = conn.event_tx.send(signal);
                    }
                }
            }
            WsCommand::LockGet { locks } => {
                for (server, owner) in locks.into_iter().take(256) {
                    let links = inner.locks.get(&super::join_lock::record_key(&server, &owner)).cloned().unwrap_or_default();
                    let read = WsEvent::LockChain { server, links, put: None };
                    if let Some(held) = inner.held_lock_reads.get_mut(from) {
                        held.push(read);
                    } else if let Some(conn) = inner.conns.get(from) {
                        let _ = conn.event_tx.send(read);
                    }
                }
            }
            WsCommand::LockPut { server, owner, links } => {
                let before = inner.room_door(&server);
                let (current, accepted) = relay_lock_put(&mut inner.locks, &server, &owner, &links);
                let after = inner.room_door(&server);
                if after.is_some() && after != before {
                    inner.relock(&server, before.is_some());
                }
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::LockChain { server, links: current, put: Some(accepted) });
                }
            }
            WsCommand::KillAck { signal } => {
                // The only removal a client can ask for, and always its own: the
                // one signal it names by issuer and stamp, or every one.
                inner.kill_acks.push((from.to_string(), signal.clone()));
                match signal {
                    None => {
                        inner.kill_list.remove(from);
                    }
                    Some(s) => {
                        if let Some(slots) = inner.kill_list.get_mut(from) {
                            slots.retain(|e| e.issuer != s.issuer || e.issued_at_ms != s.issued_at_ms);
                            if slots.is_empty() {
                                inner.kill_list.remove(from);
                            }
                        }
                    }
                }
            }
            WsCommand::ClaimLinkCode { code } => {
                let code = code.to_uppercase();
                inner.link_codes.retain(|_, owner| owner != from);
                let reply = if inner.link_codes.contains_key(&code) {
                    WsEvent::LinkCodeError { error: "taken".into(), code: String::new() }
                } else {
                    inner.link_codes.insert(code.clone(), from.to_string());
                    WsEvent::LinkCodeClaimed { code }
                };
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(reply);
                }
            }
            WsCommand::ReleaseLinkCode => {
                inner.link_codes.retain(|_, owner| owner != from);
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(WsEvent::LinkCodeReleased);
                }
            }
            WsCommand::ResolveLinkCode { code } => {
                let code = code.to_uppercase();
                let reply = match inner.link_codes.remove(&code) {
                    Some(peer_id) => WsEvent::LinkCodeResolved { code, peer_id },
                    None => WsEvent::LinkCodeError { error: "not_found".into(), code },
                };
                if let Some(conn) = inner.conns.get(from) {
                    let _ = conn.event_tx.send(reply);
                }
            }
            WsCommand::SendChannelDirect { room_code, target_peer, .. } => {
                // Only from a socket that sees the room; a member who got the room's
                // broadcast needs no copy.
                if !inner.peer_in_room(&room_code, from)
                    || !inner.receives(&room_code, from)
                    || !RelayInner::paired(&room_code, from, &target_peer)
                    || (inner.peer_in_room(&room_code, &target_peer) && inner.receives(&room_code, &target_peer))
                {
                    return;
                }
                inner.channel_copies.push((from.to_string(), room_code, target_peer));
            }
            // The push registries: not needed for the current tests, so a no-op
            // (add when a test does).
            _ => {}
        }
    }
}

/// What the relay holds for one master: every roster shown for it, folded, and when it
/// first saw each pending join.
struct InboxRoster {
    roster: crate::identity::roster::Roster,
    /// `base|device` -> first sight.
    seen: HashMap<String, i64>,
}

impl RelayInner {
    /// Fold a roster shown on an `inbox:` join into the one held for its master and
    /// say whether `from` is a member of the result, as the relay does: anyone's shown
    /// statements are kept (each verifies alone), the relay's own clock times pending
    /// joins, and a change that drops a member drops its inbox at once.
    fn show_roster(&mut self, from: &str, room: &str, shown: crate::identity::roster::Roster) -> bool {
        let Some(master) = room.strip_prefix("inbox:").map(str::to_string) else { return false };
        let too_big = serde_json::to_vec(&shown).map_or(true, |b| b.len() > crate::identity::roster::MAX_ROSTER_BYTES);
        if shown.master != master || too_big || !shown.within_caps() {
            return false;
        }
        let now = super::roster_book::now_ms();
        let held = self.inbox_rosters.entry(master.clone()).or_insert_with(|| InboxRoster {
            roster: crate::identity::roster::Roster::new(&master),
            seen: HashMap::new(),
        });
        let merged = held.roster.merged(&shown.verified(now));
        // First sights per base, as `RosterBook::seen_key`: a recovery restarts them.
        let seen: HashMap<String, i64> = merged
            .pendings
            .iter()
            .map(|p| {
                let key = format!("{}|{}", p.base, p.device);
                let first = held.seen.get(&key).copied().unwrap_or(now);
                (key, first)
            })
            .collect();
        let changed = merged != held.roster || seen != held.seen;
        held.roster = merged;
        held.seen = seen;
        let base = held.roster.base();
        let state = held.roster.fold(|d| held.seen.get(&format!("{base}|{d}")).copied(), now);
        if changed {
            self.drop_inbox_owners(room, &state.members);
        }
        state.is_member(from)
    }

    /// Owners of `room` the fold stopped counting lose the inbox now; the others see
    /// them leave.
    fn drop_inbox_owners(&mut self, room: &str, members: &std::collections::BTreeSet<String>) {
        let gone: Vec<String> = self
            .inbox_owners
            .get(room)
            .map(|o| o.iter().filter(|d| !members.contains(*d)).cloned().collect())
            .unwrap_or_default();
        for d in gone {
            if let Some(owners) = self.inbox_owners.get_mut(room) {
                owners.remove(&d);
            }
            self.broadcast_except(room, &d, WsEvent::PeerLeft { room: room.to_string(), peer_id: d.clone() });
        }
    }

    /// Whether `peer` sees and receives in `room`: everywhere, except that an inbox
    /// shows only its owners and a door-locked server room only its provers.
    fn receives(&self, room: &str, peer: &str) -> bool {
        if room.starts_with("inbox:") {
            return self.inbox_owners.get(room).is_some_and(|o| o.contains(peer));
        }
        self.room_door(room).is_none() || self.sees_door(room, peer)
    }

    /// Whether a direct for `peer` in `room` reaches it: a locked room's members choose
    /// whom to address, so only an inbox holds one back.
    fn reachable(&self, room: &str, peer: &str) -> bool {
        !room.starts_with("inbox:") || self.inbox_owners.get(room).is_some_and(|o| o.contains(peer))
    }

    /// Whether `a` and `b` may know of and reach each other in `room`: in a forwarder's
    /// room `fwd:{X}` only X and one other member, as on the relay (`fwd_room.h`).
    fn paired(room: &str, a: &str, b: &str) -> bool {
        room.strip_prefix("fwd:").is_none_or(|x| a == x || b == x)
    }

    /// Whether `pid` sees `room` and may know of `other` there.
    fn shares(&self, room: &str, pid: &str, other: &str) -> bool {
        self.receives(room, pid) && Self::paired(room, pid, other)
    }

    /// The newest door of a self-certifying server room with a lock here: the room is
    /// door-locked.
    fn room_door(&self, room: &str) -> Option<String> {
        if !crate::crdt::anchor::is_genesis_id(room) {
            return None;
        }
        self.locks.get(room).and_then(|chain| chain.last()).map(|tip| tip.door.clone())
    }

    fn sees_door(&self, room: &str, peer: &str) -> bool {
        if self.kept_in_view.contains(&(room.to_string(), peer.to_string())) {
            return true;
        }
        match self.provers.get(room).and_then(|p| p.get(peer)) {
            Some(None) => true,
            Some(Some(until)) => std::time::Instant::now() < *until,
            None => false,
        }
    }

    fn proves_door(&self, room: &str, peer: &str, door: &str) -> bool {
        self.doors_held.get(peer).and_then(|d| d.get(room)).is_some_and(|held| held == door)
    }

    /// The newest door of `room` changed, or the room just became locked: whoever holds
    /// the new door proves at once, anyone else who could see keeps seeing for the grace.
    fn relock(&mut self, room: &str, was_locked: bool) {
        let Some(door) = self.room_door(room) else { return };
        let until = std::time::Instant::now() + MOCK_DOOR_GRACE;
        let peers: Vec<String> = self.rooms.get(room).map(|s| s.iter().cloned().collect()).unwrap_or_default();
        let mut newly = Vec::new();
        for peer in peers {
            let saw = !was_locked || self.sees_door(room, &peer);
            let proves = self.proves_door(room, &peer, &door);
            let provers = self.provers.entry(room.to_string()).or_default();
            if proves {
                provers.insert(peer.clone(), None);
                if !saw {
                    newly.push(peer);
                }
            } else if saw {
                let keep = provers.get(&peer).copied().flatten().filter(|t| *t < until).unwrap_or(until);
                provers.insert(peer, Some(keep));
            } else {
                provers.remove(&peer);
            }
        }
        for peer in newly {
            self.announce_seen(room, &peer);
        }
    }

    /// `peer` sees `room` now: its roster to it, `PeerJoined` to the others.
    fn announce_seen(&self, room: &str, peer: &str) {
        let mut members: Vec<String> = self
            .rooms
            .get(room)
            .map(|s| s.iter().filter(|p| *p != peer && self.receives(room, p)).cloned().collect())
            .unwrap_or_default();
        members.push(peer.to_string());
        if let Some(conn) = self.conns.get(peer).filter(|c| c.online) {
            let _ = conn.event_tx.send(WsEvent::DoorStatus { room: room.to_string(), proved: true });
            let _ = conn.event_tx.send(WsEvent::RoomMembers { room: room.to_string(), peers: members });
        }
        self.broadcast_except(room, peer, WsEvent::PeerJoined { room: room.to_string(), peer_id: peer.to_string() });
    }

    /// Provers whose grace ran out stop seeing: the others see them leave, and each is
    /// told it sees only itself, as the relay's sweep does.
    fn sweep_doors(&mut self) {
        let now = std::time::Instant::now();
        let mut gone: Vec<(String, String)> = Vec::new();
        for (room, provers) in self.provers.iter_mut() {
            provers.retain(|peer, until| {
                let keep = until.is_none_or(|t| now < t);
                if !keep {
                    gone.push((room.clone(), peer.clone()));
                }
                keep
            });
        }
        for (room, peer) in gone {
            if self.room_door(&room).is_none() || !self.peer_in_room(&room, &peer) || self.sees_door(&room, &peer) {
                continue;
            }
            self.broadcast_except(&room, &peer, WsEvent::PeerLeft { room: room.clone(), peer_id: peer.clone() });
            if let Some(conn) = self.conns.get(&peer).filter(|c| c.online) {
                let _ = conn.event_tx.send(WsEvent::DoorStatus { room: room.clone(), proved: false });
                let _ = conn.event_tx.send(WsEvent::RoomMembers { room: room.clone(), peers: vec![peer.clone()] });
            }
        }
    }

    /// A join as the relay handles it: the roster to the joiner, `PeerJoined` to the
    /// others, the joiner's own buffered frames. An inbox shows an owner only the other
    /// owners and a non-owner nobody, and tells nobody about a non-owner; a door-locked
    /// room does the same for its provers.
    fn join(&mut self, from: &str, room: &str, owner: bool) {
        let inbox = room.starts_with("inbox:");
        // A connection that proved it once stays an owner through a plain re-join.
        let owner = owner || (inbox && self.peer_in_room(room, from) && self.receives(room, from));
        if inbox {
            let owners = self.inbox_owners.entry(room.to_string()).or_default();
            if owner {
                owners.insert(from.to_string());
            } else {
                owners.remove(from);
            }
        }
        // A door-locked room: a join that proves the newest door makes a prover, a
        // re-join keeps what it had, a new socket proves again.
        let door_ok = match self.room_door(room) {
            None => true,
            Some(door) => {
                let proves = self.proves_door(room, from, &door);
                let in_room = self.peer_in_room(room, from);
                let provers = self.provers.entry(room.to_string()).or_default();
                if proves {
                    provers.insert(from.to_string(), None);
                } else if !in_room {
                    provers.remove(from);
                }
                self.sees_door(room, from)
            }
        };
        let visible = (!inbox || owner) && door_ok;
        let existing: Vec<String> = if visible {
            self.rooms
                .get(room)
                .map(|s| s.iter().filter(|p| *p != from && self.shares(room, p, from)).cloned().collect())
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        self.rooms.entry(room.to_string()).or_default().insert(from.to_string());

        // members snapshot to the joiner (includes self, like the relay).
        let mut members = existing.clone();
        members.push(from.to_string());
        if let Some(conn) = self.conns.get(from) {
            let _ = conn.event_tx.send(WsEvent::DoorStatus { room: room.to_string(), proved: door_ok });
            let _ = conn.event_tx.send(WsEvent::RoomMembers {
                room: room.to_string(),
                peers: members,
            });
        }
        for m in &existing {
            if let Some(conn) = self.conns.get(m) {
                let _ = conn.event_tx.send(WsEvent::PeerJoined {
                    room: room.to_string(),
                    peer_id: from.to_string(),
                });
            }
        }
        self.replay_offline(from, room);
    }

    /// Record one outgoing frame when a test has armed recording for its sender.
    fn on_the_wire(&mut self, from: &str, _room: &str, _route: &str, data: Vec<u8>) -> Vec<u8> {
        if self.recording.contains(from) {
            self.recorded.push((from.to_string(), data.clone()));
        }
        data
    }

    /// `data` as `from` would put it on the wire: already sealed frames (a capture)
    /// pass unchanged, a bare body is sealed with `from`'s key when the relay knows it.
    fn sealed_as(&self, from: &str, room: &str, route: &str, data: Vec<u8>) -> Vec<u8> {
        if data.starts_with(&super::frame_auth::MAGIC) {
            return data;
        }
        match self.keys.get(from) {
            Some(kp) => super::frame_auth::seal(kp, room, route, &data),
            None => data,
        }
    }

    fn peer_in_room(&self, room: &str, peer: &str) -> bool {
        self.rooms.get(room).map(|s| s.contains(peer)).unwrap_or(false)
    }

    /// [`Self::broadcast_except`] for 0x03 DATA frames: additionally skips
    /// `broadcast_deaf` devices (the backpressure-drop lever). Presence events
    /// keep using `broadcast_except` directly — the real relay's drop hits
    /// data frames on a wedged socket, not the membership protocol.
    fn broadcast_data_except(&mut self, room: &str, from: &str, event: WsEvent) -> u64 {
        let members: Vec<String> = self
            .rooms
            .get(room)
            .map(|s| s.iter().cloned().collect())
            .unwrap_or_default();
        let mut delivered = 0u64;
        for m in members {
            if m == from || self.broadcast_deaf.contains(&m) || !self.shares(room, &m, from) {
                continue;
            }
            if let Some(held) = self.held_broadcasts.get_mut(&(from.to_string(), m.clone())) {
                held.push(event.clone());
                continue;
            }
            if let Some(conn) = self.conns.get(&m).filter(|c| c.online) {
                let _ = conn.event_tx.send(event.clone());
                delivered += 1;
            }
        }
        delivered
    }

    /// Broadcast to every online room member except the sender. Returns the
    /// number of frames actually delivered to a socket (the relay egress for
    /// this one command — this is the O(N) fan-out the benchmark measures).
    fn broadcast_except(&self, room: &str, from: &str, event: WsEvent) -> u64 {
        let members: Vec<String> = self
            .rooms
            .get(room)
            .map(|s| s.iter().cloned().collect())
            .unwrap_or_default();
        let mut delivered = 0u64;
        for m in members {
            if m == from {
                continue; // no self-echo (matches relay)
            }
            if !self.shares(room, &m, from) {
                continue;
            }
            if let Some(conn) = self.conns.get(&m).filter(|c| c.online) {
                let _ = conn.event_tx.send(event.clone());
                delivered += 1;
            }
        }
        delivered
    }

    /// Deliver (or buffer) a direct frame. Returns 1 if it was delivered to a
    /// live socket, 0 if buffered offline (no egress now).
    fn deliver_direct(&mut self, room: &str, from: &str, target: &str, data: Vec<u8>, direct: bool) -> u64 {
        if !Self::paired(room, from, target) {
            return 0;
        }
        if self.swallowed_directs.contains(&(from.to_string(), target.to_string())) {
            return 0;
        }
        if let Some(held) = self.held_directs.get_mut(&(from.to_string(), target.to_string())) {
            held.push(BufferedMsg { room: room.to_string(), from: from.to_string(), data, direct });
            return 0;
        }
        if self.peer_in_room(room, target) && !self.reachable(room, target) {
            return 0;
        }
        let online = self.conns.get(target).map(|c| c.online).unwrap_or(false);
        if room.strip_prefix("inbox:") == Some(target) {
            // A deposit for the inbox's own master: kept in the mailbox AND handed to
            // the owners online now, who alone know which devices they are.
            let owners: Vec<String> = self
                .inbox_owners
                .get(room)
                .map(|o| o.iter().filter(|p| *p != from).cloned().collect())
                .unwrap_or_default();
            let mut delivered = 0;
            for owner in owners {
                if let Some(conn) = self.conns.get(&owner).filter(|c| c.online) {
                    let _ = conn.event_tx.send(WsEvent::DirectMessage {
                        room: room.to_string(),
                        from: from.to_string(),
                        data: data.clone(),
                    });
                    delivered += 1;
                }
            }
            self.offline.entry(target.to_string()).or_default().push(BufferedMsg {
                room: room.to_string(),
                from: from.to_string(),
                data,
                direct,
            });
            return delivered;
        }
        if online && self.peer_in_room(room, target) {
            if let Some(conn) = self.conns.get(target) {
                let _ = conn.event_tx.send(WsEvent::DirectMessage {
                    room: room.to_string(),
                    from: from.to_string(),
                    data,
                });
            }
            return 1;
        } else {
            // Target offline (or connected but not in the room): buffer for
            // replay on the target's next join of this room. This is the
            // load-bearing peer-fallback path.
            self.offline.entry(target.to_string()).or_default().push(BufferedMsg {
                room: room.to_string(),
                from: from.to_string(),
                data,
                direct,
            });
            0
        }
    }

    /// Replay a MASTER's mailbox to a socket that has PROVEN it owns that inbox.
    ///
    /// TTL-only, NOT delete-on-replay: every sibling device must be able to collect
    /// the same request on its own next boot, so consuming it for the first device to
    /// ask would hide it from the rest. The receiver dedups on its friends row, which
    /// is what makes re-delivery harmless. Per-socket "already delivered" tracking is
    /// delete-on-replay wearing a hat.
    fn replay_mailbox(&mut self, peer: &str, master: &str) {
        let Some(buf) = self.offline.get(master) else { return };
        let frames: Vec<(String, String, Vec<u8>, bool)> = buf
            .iter()
            .map(|m| (m.room.clone(), m.from.clone(), m.data.clone(), m.direct))
            .collect();
        let Some(conn) = self.conns.get(peer) else { return };
        if !conn.online {
            return;
        }
        for (room, from, data, direct) in frames {
            let ev = if direct {
                WsEvent::DirectMessage { room, from, data }
            } else {
                WsEvent::Message { room, from, data }
            };
            let _ = conn.event_tx.send(ev);
        }
    }

    fn replay_offline(&mut self, peer: &str, room: &str) {
        let Some(buf) = self.offline.get_mut(peer) else { return };
        let (replay, keep): (Vec<_>, Vec<_>) = std::mem::take(buf).into_iter().partition(|m| m.room == room);
        *buf = keep;
        let Some(conn) = self.conns.get(peer) else { return };
        if !conn.online {
            return;
        }
        for m in replay {
            let ev = if m.direct {
                WsEvent::DirectMessage { room: m.room, from: m.from, data: m.data }
            } else {
                WsEvent::Message { room: m.room, from: m.from, data: m.data }
            };
            let _ = conn.event_tx.send(ev);
        }
    }
}

// ---------------------------------------------------------------------------
// TestNode — one running node + handles to drive/observe it.
// ---------------------------------------------------------------------------

pub(crate) struct TestNode {
    /// MASTER identity peer_id (friendships, DM convo key, display).
    pub master_id: String,
    /// DEVICE transport peer_id (relay routing).
    pub device_id: String,
    pub cmd_tx: mpsc::Sender<NodeCommand>,
    pub event_rx: mpsc::Receiver<NetworkEvent>,
    pub db_path: String,
    pub passphrase: String,
    /// This node's private data root. Production reads it from the global
    /// `data_dir()`, which several nodes in one process cannot share, so the wipe
    /// routine takes it explicitly.
    pub data_root: std::path::PathBuf,
    /// This node's MASTER keypair — the key its own event loop signs CRDT ops
    /// with. A test that has to forge (or legitimately author) an op on a
    /// node's behalf needs it, because a CrdtOp is bound to its author by
    /// signature now.
    pub master_kp: NativeKeypair,
    _join: AbortOnDrop,
    // Keep the tempdir alive for the node's lifetime.
    _tmp: crate::test_tmp::TestDir,
}

/// Stops a node's event loop with its `TestNode`: a dropped `JoinHandle` only
/// detaches the task, and a detached node goes on writing into its data dirs while
/// the test tears them down. Waits until the loop is gone, not just told, since a
/// poll still running would write after the drop too.
struct AbortOnDrop(tokio::task::JoinHandle<()>);

impl Drop for AbortOnDrop {
    fn drop(&mut self) {
        self.0.abort();
        // Only another worker can finish the abort; a current-thread runtime waits on us.
        let multi = tokio::runtime::Handle::try_current()
            .is_ok_and(|rt| rt.runtime_flavor() == tokio::runtime::RuntimeFlavor::MultiThread);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while multi && !self.0.is_finished() && std::time::Instant::now() < deadline {
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }
}

impl TestNode {
    fn store(&self) -> crate::storage::MessageStore {
        crate::storage::MessageStore::open(&self.db_path, &self.passphrase)
            .expect("open node store")
    }

    /// End this node's life and hand back the storage a RESTART needs: the DB path
    /// and the tempdir that owns it.
    ///
    /// Aborting the join handle is what a process exit does to the event loop, and
    /// the store actors die with it, which is what lets the file be reopened.
    fn into_storage(self) -> (String, crate::test_tmp::TestDir) {
        self._join.0.abort();
        (self.db_path, self._tmp)
    }
}

// Inspectors: read a node's REAL state the way the UI does, in two layers,
// because the gap between them is where multi-device bugs hide. The UI layer is
// master-collapsed and reads through the same accessors the Dart providers use;
// the raw layer is device-keyed underlying truth, so a test can assert the
// invariant beneath the UI. DB-backed state comes from the node's own SQLCipher
// store; presence comes from the MockRelay, which is authoritative.

/// One DM bubble as the chat UI would render it.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct DmBubble {
    pub text: String,
    /// Right-aligned (our send) vs left (received) — the `is_mine` the UI uses.
    pub is_mine: bool,
    pub timestamp: i64,
    /// Whether a signature was present (None => unsigned, shows the "Unsigned" tag).
    pub has_sig: bool,
}

/// One member-panel row as the UI would render it (master-keyed).
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct MemberRow {
    pub master: String,
    pub role: crate::crdt::operations::MemberRole,
    pub online: bool,
}

/// One channel message as the UI would render it.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct ChannelMsg {
    pub text: String,
    /// The SENDER collapsed to their master identity (the name the UI shows).
    pub sender_master: String,
    pub is_mine: bool,
    pub timestamp: i64,
    /// Microsecond ordering key (Step 9C/C4) — `None` if it didn't survive the
    /// wire/backfill (a regression) or a legacy/pre-9C row.
    pub order_us: Option<i64>,
}

#[allow(dead_code)] // Inspector API — methods are used as scenarios are added.
impl TestNode {
    // --- DM thread (UI layer) ----------------------------------------------

    /// The DM thread with `friend_master`, ordered oldest-first, exactly as the
    /// chat pane would show it (bubbles with side + signed flag). Resolves the
    /// friend to their master so a multi-device friend's thread still keys
    /// correctly (the conversation is master-keyed).
    pub(crate) fn dm_thread(&self, friend_master: &str) -> Vec<DmBubble> {
        let convo = super::resolver::resolve(friend_master);
        self.store()
            .get_dm_messages_for_sibling(&convo, 0, 1000)
            .unwrap_or_default()
            .into_iter()
            .map(|m| DmBubble {
                text: m.text,
                is_mine: m.is_mine,
                timestamp: m.timestamp,
                has_sig: m.signature.is_some(),
            })
            .collect()
    }

    /// Unread-count pill for a DM conversation, as the nav would show it.
    pub(crate) fn dm_unread(&self, friend_master: &str, last_seen_message_id: &str) -> u32 {
        let convo = super::resolver::resolve(friend_master);
        self.store().count_unread_dm(&convo, last_seen_message_id)
    }

    // --- Servers / channels / members (UI layer) ---------------------------

    /// Server ids this node is a member of (what the server strip shows), mirroring
    /// `get_joined_servers`: a tombstoned server is HIDDEN (the shell is kept only to
    /// serve the deletion op), and so is a shell we are no longer a member of.
    pub(crate) fn servers(&self) -> Vec<String> {
        self.store()
            .load_all_servers()
            .unwrap_or_default()
            .into_iter()
            .filter(|(_, json)| {
                serde_json::from_str::<ServerState>(json)
                    .map(|s| {
                        !s.is_deleted()
                            && (s.members.is_empty() || s.is_member(&self.master_id))
                    })
                    .unwrap_or(true)
            })
            .map(|(sid, _)| sid)
            .collect()
    }

    /// Parked/rejected join rows as `list_pending_joins` would hand them to the
    /// UI: `(server_id, state, reason)`, newest ask first. Reads the same table
    /// through the same accessor the FFI does.
    pub(crate) fn pending_joins(&self) -> Vec<(String, String, String)> {
        self.store()
            .load_pending_joins()
            .unwrap_or_default()
            .into_iter()
            .map(|r| (r.server_id, r.state, r.reason))
            .collect()
    }

    /// Load one server's CRDT state (None if not joined).
    fn server_state(&self, server_id: &str) -> Option<ServerState> {
        let json = self.store().load_server_state(server_id).ok().flatten()?;
        serde_json::from_str::<ServerState>(&json).ok()
    }

    /// A LIVE clone of the event loop's in-memory `ServerState`, the copy that
    /// ENFORCES, round-tripped exactly as `api::crdt::live_server_state` does.
    ///
    /// Prefer this over `server_state` when asserting that a hostile op did NOT land:
    /// the DB snapshot is written by a fire-and-forget actor, and polling SQLCipher
    /// starves that writer. `None` means the loop never answered, never "no change".
    pub(crate) async fn live_server_state(&self, server_id: &str) -> Option<ServerState> {
        let (tx, rx) = tokio::sync::oneshot::channel();
        self.cmd_tx
            .send(NodeCommand::GetServerStateSnapshot {
                server_id: server_id.to_string(),
                reply: tx,
            })
            .await
            .ok()?;
        tokio::time::timeout(std::time::Duration::from_secs(5), rx)
            .await
            .ok()?
            .ok()?
    }

    /// A member's role as the LIVE state holds it. Panics if the loop does not
    /// answer or does not hold the server: a timed-out probe is not a role.
    pub(crate) async fn live_role(
        &self,
        server_id: &str,
        master: &str,
    ) -> crate::crdt::operations::MemberRole {
        self.live_server_state(server_id)
            .await
            .unwrap_or_else(|| panic!("no live state for {server_id}"))
            .get_role(master)
    }

    /// The server name as the LIVE state holds it. Panics like `live_role`.
    pub(crate) async fn live_server_name(&self, server_id: &str) -> String {
        self.live_server_state(server_id)
            .await
            .unwrap_or_else(|| panic!("no live state for {server_id}"))
            .name()
            .to_string()
    }

    /// The Owner the LIVE state currently recognises. Panics like `live_role`.
    pub(crate) async fn live_owner(&self, server_id: &str) -> Option<String> {
        self.live_server_state(server_id)
            .await
            .unwrap_or_else(|| panic!("no live state for {server_id}"))
            .current_owner()
    }

    /// The member panel for `server_id`, master-keyed with role + online flag —
    /// exactly the rows the member panel renders. `relay` supplies authoritative
    /// presence. Roles/membership go through `ServerState::get_role` (which
    /// collapses device→master internally, the resolver-hook chokepoint).
    pub(crate) fn member_panel(&self, server_id: &str, relay: &MockRelay) -> Vec<MemberRow> {
        let Some(state) = self.server_state(server_id) else { return Vec::new() };
        let online_masters = online_identities_from(relay);
        let mut rows: Vec<MemberRow> = state
            .members
            .keys()
            .map(|master| MemberRow {
                master: master.clone(),
                role: state.get_role(master),
                online: online_masters.contains(master),
            })
            .collect();
        rows.sort_by(|a, b| a.master.cmp(&b.master));
        rows
    }

    /// A member's server nickname as the UI would read it (master-keyed, collapses
    /// device→master via `get_nickname`'s resolver). Empty string = no nickname.
    pub(crate) fn server_nickname(&self, server_id: &str, master: &str) -> String {
        self.server_state(server_id)
            .map(|s| s.get_nickname(master))
            .unwrap_or_default()
    }

    /// A server setting as the UI reads it via `get_server_setting`
    /// (None = never set).
    pub(crate) fn server_setting(&self, server_id: &str, key: &str) -> Option<String> {
        self.server_state(server_id)?
            .settings
            .get(key)
            .map(|r| r.read().clone())
    }

    /// A channel's messages, oldest-first, as the channel pane shows them
    /// (sender collapsed to master).
    pub(crate) fn channel_messages(&self, server_id: &str, channel_id: &str) -> Vec<ChannelMsg> {
        self.store()
            .load_channel_messages(server_id, channel_id, 1000)
            .unwrap_or_default()
            .into_iter()
            .map(|m| ChannelMsg {
                sender_master: super::resolver::resolve(&m.sender_id),
                text: m.text,
                is_mine: m.is_mine,
                timestamp: m.timestamp,
                order_us: m.order_us,
            })
            .collect()
    }

    /// A channel's visibility tier as the UI reads it via `get_server_channels`
    /// ("everyone" | "moderator" | "admin"). This is the exact value
    /// `visibleChannelsProvider` filters on — green here == the UI would hide/show
    /// correctly. None if the channel/server is unknown.
    pub(crate) fn channel_visibility(&self, server_id: &str, channel_id: &str) -> Option<String> {
        let state = self.server_state(server_id)?;
        let ch = state.channels.get(channel_id)?;
        Some(match ch.visibility {
            crate::crdt::server_state::ChannelVisibility::Everyone => "everyone",
            crate::crdt::server_state::ChannelVisibility::ModeratorPlus => "moderator",
            crate::crdt::server_state::ChannelVisibility::AdminPlus => "admin",
        }.to_string())
    }

    /// A channel's posting tier as the UI reads it ("everyone"|"moderator"|"admin").
    /// Mirrors `canPostInChannelProvider`'s channel-mode input. None if unknown.
    pub(crate) fn channel_posting(&self, server_id: &str, channel_id: &str) -> Option<String> {
        let state = self.server_state(server_id)?;
        let ch = state.channels.get(channel_id)?;
        Some(match ch.posting {
            crate::crdt::server_state::ChannelPosting::Everyone => "everyone",
            crate::crdt::server_state::ChannelPosting::ModeratorPlus => "moderator",
            crate::crdt::server_state::ChannelPosting::AdminPlus => "admin",
        }.to_string())
    }

    /// A channel's slow-mode interval (seconds, 0 = off) as the UI reads it.
    pub(crate) fn channel_slow_mode(&self, server_id: &str, channel_id: &str) -> Option<u32> {
        let state = self.server_state(server_id)?;
        Some(state.channels.get(channel_id)?.slow_mode)
    }

    /// A channel's visibility label gate (label ids; empty = no gate). None
    /// if the channel/server is unknown.
    pub(crate) fn channel_visibility_labels(&self, server_id: &str, channel_id: &str) -> Option<Vec<String>> {
        let state = self.server_state(server_id)?;
        Some(state.channels.get(channel_id)?.visibility_labels.clone())
    }

    /// A channel's posting label gate (label ids; empty = no gate).
    pub(crate) fn channel_posting_labels(&self, server_id: &str, channel_id: &str) -> Option<Vec<String>> {
        let state = self.server_state(server_id)?;
        Some(state.channels.get(channel_id)?.posting_labels.clone())
    }

    /// The label ids assigned to a member (raw master-keyed lookup, sorted).
    pub(crate) fn member_label_ids(&self, server_id: &str, master: &str) -> Vec<String> {
        let mut ids = self
            .server_state(server_id)
            .and_then(|s| s.label_assignments.get(master).cloned())
            .unwrap_or_default();
        ids.sort();
        ids
    }

    /// A label's access flag (None = label unknown).
    pub(crate) fn label_access(&self, server_id: &str, label_id: &str) -> Option<bool> {
        self.server_state(server_id)?
            .labels
            .get(label_id)
            .map(|l| l.access)
    }

    /// Whether `peer` holds an unexpired temporary grant for the channel
    /// RIGHT NOW — the moving part `can_see_channel`/`can_post_in_channel`
    /// evaluate (mirrors `is_muted_now`).
    pub(crate) fn has_grant_now(&self, server_id: &str, channel_id: &str, peer: &str) -> bool {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64;
        self.server_state(server_id)
            .map(|s| s.has_channel_grant(peer, channel_id, now))
            .unwrap_or(false)
    }

    /// A channel's media-only flag as the UI reads it.
    pub(crate) fn channel_media_only(&self, server_id: &str, channel_id: &str) -> Option<bool> {
        let state = self.server_state(server_id)?;
        Some(state.channels.get(channel_id)?.media_only)
    }

    /// Whether `peer` is muted RIGHT NOW per this node's CRDT state — exactly
    /// the predicate the send/ingest moderation gates evaluate.
    pub(crate) fn is_muted_now(&self, server_id: &str, peer: &str) -> bool {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64;
        self.server_state(server_id)
            .map(|s| s.is_muted(peer, now))
            .unwrap_or(false)
    }

    /// Whether this node's local user can SEE a channel — exactly what
    /// `visibleChannelsProvider` computes (role tier vs channel visibility). The
    /// UI hides the channel + evicts the user when this flips to false.
    pub(crate) fn can_see_channel(&self, server_id: &str, channel_id: &str, me: &str) -> bool {
        self.server_state(server_id)
            .map(|s| s.can_see_channel(me, channel_id))
            .unwrap_or(false)
    }

    // --- Raw layer (device-keyed underlying truth) -------------------------

    /// The RAW CRDT member keys for a server (as stored). In a correct
    /// multi-device world these are MASTER ids; if a device id leaks in here,
    /// `canonicalize_members` failed — a bug invisible in the master-collapsed
    /// member panel but visible here.
    pub(crate) fn raw_crdt_member_keys(&self, server_id: &str) -> Vec<String> {
        let Some(state) = self.server_state(server_id) else { return Vec::new() };
        let mut keys: Vec<String> = state.members.keys().cloned().collect();
        keys.sort();
        keys
    }

    /// The RAW `sender_id` a channel message row is stored under, NOT collapsed
    /// device to master. A stored sender must be the sender's MASTER; a leaked DEVICE
    /// id means the receive path stored it unresolved, which the collapsed
    /// `channel_messages` inspector hides by resolving on read.
    pub(crate) fn raw_channel_message_sender(&self, message_id: &str) -> Option<String> {
        self.store().get_channel_message_sender(message_id)
    }

    // --- Live crypto state (queries the running event loop) ----------------

    /// Snapshot the node's LIVE in-memory MLS/Olm state (owned by the running
    /// event loop). Round-trips a `DebugSnapshot` command over the oneshot.
    /// Returns `None` if the loop didn't reply within the timeout.
    pub(crate) async fn debug_snapshot(&self) -> Option<super::types::DebugSnapshotReply> {
        let (tx, rx) = tokio::sync::oneshot::channel();
        self.cmd_tx
            .send(NodeCommand::DebugSnapshot { reply: tx })
            .await
            .ok()?;
        // 5s, not 2: under a full parallel run the event loop is busy and a
        // 2s round trip timed out, which `olm_status` then reports as "absent"
        // and `mls_members` as an empty group. Both read as real state.
        tokio::time::timeout(std::time::Duration::from_secs(5), rx)
            .await
            .ok()?
            .ok()
    }

    /// Every message this node aimed at `device` over the Olm lane, whether or not a
    /// session let it go out: what it sent a device that cannot read it yet.
    pub(crate) async fn carried_to(&self, device: &str) -> Vec<super::types::HavenMessage> {
        self.debug_snapshot()
            .await
            .map(|s| s.carried)
            .unwrap_or_default()
            .into_iter()
            .filter(|(to, _)| to == device)
            .filter_map(|(_, json)| match serde_json::from_str::<super::types::MessageEnvelope>(&json) {
                Ok(super::types::MessageEnvelope::Carried { msg, .. }) => Some(*msg),
                _ => None,
            })
            .collect()
    }

    /// Every message of wire `kind` this node sent over the Olm lane, to anyone, as
    /// the JSON a plaintext frame of it would have carried: the Olm-lane twin of
    /// [`frames_of_type`].
    pub(crate) async fn carried_of_type(&self, kind: &str) -> Vec<serde_json::Value> {
        self.debug_snapshot()
            .await
            .map(|s| s.carried)
            .unwrap_or_default()
            .into_iter()
            .filter_map(|(_, json)| match serde_json::from_str::<super::types::MessageEnvelope>(&json) {
                Ok(super::types::MessageEnvelope::Carried { msg, .. }) => serde_json::to_value(*msg).ok(),
                _ => None,
            })
            .filter(|v| v.get("type").and_then(|t| t.as_str()) == Some(kind))
            .collect()
    }

    /// Whether the LOOP still believes `device` shares a room with us. The relay
    /// drops a peer before the node hears about it, so this is what a test waits on
    /// before asserting how a send was routed.
    pub(crate) async fn sees_peer(&self, device: &str) -> bool {
        self.debug_snapshot()
            .await
            .map(|s| s.room_peers.iter().any(|p| p == device))
            .unwrap_or(true)
    }

    /// The live pending join for `server_id` as (`opened_at`, parked); `None` when there
    /// is none or the loop did not reply, so it never reads as "not parked".
    pub(crate) async fn pending_ask(&self, server_id: &str) -> Option<(i64, bool)> {
        self.debug_snapshot().await?.pending_asks.get(server_id).copied()
    }

    /// The MLS group's leaf DEVICE ids for `group_id`, telling "the loop did not
    /// reply" (None) apart from "the group holds no such leaf" (empty). An EVICTION
    /// wait MUST use this: a timed-out snapshot yields an empty list, which reads
    /// exactly like a successful removal.
    pub(crate) async fn mls_members_checked(&self, group_id: &str) -> Option<Vec<String>> {
        let mut v = self.debug_snapshot().await?.mls_members.get(group_id).cloned().unwrap_or_default();
        v.sort();
        Some(v)
    }

    pub(crate) async fn mls_members(&self, server_id: &str) -> Vec<String> {
        let mut v = self
            .debug_snapshot()
            .await
            .and_then(|s| s.mls_members.get(server_id).cloned())
            .unwrap_or_default();
        v.sort();
        v
    }

    /// The current MLS epoch for `server_id` (None if no group / no reply).
    pub(crate) async fn mls_epoch(&self, server_id: &str) -> Option<u64> {
        self.debug_snapshot()
            .await
            .and_then(|s| s.mls_epoch.get(server_id).copied())
    }

    /// The epoch and its digest for `group_key`: two nodes agree on the group only when
    /// both match, since forks share epoch numbers.
    pub(crate) async fn mls_epoch_state(&self, group_key: &str) -> Option<(u64, String)> {
        let snap = self.debug_snapshot().await?;
        Some((*snap.mls_epoch.get(group_key)?, snap.mls_epoch_auth.get(group_key)?.clone()))
    }

    /// Olm session status with a peer DEVICE id: "none" | "unconfirmed" |
    /// "confirmed" | "absent" (no session object at all).
    /// The id of the Olm session this node encrypts with for a device.
    pub(crate) async fn olm_session_id(&self, device_peer_id: &str) -> Option<String> {
        self.debug_snapshot().await.and_then(|s| s.olm_session_ids.get(device_peer_id).cloned())
    }

    pub(crate) async fn olm_status(&self, device_peer_id: &str) -> String {
        self.debug_snapshot()
            .await
            .and_then(|s| s.olm_sessions.get(device_peer_id).cloned())
            .unwrap_or_else(|| "absent".to_string())
    }

    /// Devices removed from `master`'s roster as this node PERSISTED it. Empty
    /// when no roster is stored yet. This is the settle signal that a peer durably
    /// ingested a removal: both the sender-side device targeting and the
    /// receive-side is_revoked guard read it.
    pub(crate) fn revoked_devices(&self, master: &str) -> Vec<String> {
        let store = self.store();
        super::roster_book::load(&store, master)
            .map(|r| super::roster_book::fold(&store, &r).removed.into_keys().collect())
            .unwrap_or_default()
    }

    /// Members of `master`'s roster as this node PERSISTED it. Empty until a
    /// roster for that identity has been ingested.
    pub(crate) fn known_devices(&self, master: &str) -> Vec<String> {
        let store = self.store();
        super::roster_book::load(&store, master)
            .map(|r| super::roster_book::fold(&store, &r).members.into_iter().collect())
            .unwrap_or_default()
    }

    /// Security alerts this node has recorded (Issue 1-C). The DB is the dedup
    /// authority, so this is the assertion surface for "warned exactly once".
    pub(crate) fn security_alerts(&self) -> Vec<crate::storage::messages::SecurityAlertRow> {
        self.store().get_security_alerts().unwrap_or_default()
    }

    /// Whether this node still trusts `master`'s safety number. A destruction
    /// announce clears it, which is the assertion that matters.
    pub(crate) fn is_verified(&self, master: &str) -> bool {
        self.store().is_peer_verified(master).unwrap_or(false)
    }

    /// The stamp behind the "this identity was destroyed" banner, as the FFI reads
    /// it. `None` = no banner.
    pub(crate) fn identity_destroyed_at(&self, master: &str) -> Option<i64> {
        super::destroy::identity_destroyed_at(&self.store(), master).filter(|v| *v > 0)
    }

    /// What survives under this node's data root, as the next launch would see it.
    /// The wipe keeps the marker, any instance lock and the profile registry.
    pub(crate) fn data_root_leftovers(&self) -> Vec<String> {
        std::fs::read_dir(&self.data_root)
            .map(|rd| {
                rd.flatten()
                    .map(|e| e.file_name().to_string_lossy().to_string())
                    .filter(|n| {
                        n != "pending_wipe.marker" && n != "profiles.json" && !n.ends_with(".lock")
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Friend-table status for a person (master-keyed): "accepted", "pending",
    /// or None if no row exists. Used by the reject/mutual-request tests.
    /// This node's friend row for `master`: (status, direction, requested_at).
    pub(crate) fn friend_row(&self, master: &str) -> Option<(String, String, i64)> {
        self.store().get_friend_row(master).ok().flatten()
    }

    pub(crate) fn friend_status(&self, master: &str) -> Option<String> {
        self.store().get_friend_status(master).ok().flatten()
    }

    // --- File-transfer control state (DB-backed) ---------------------------

    /// A received file's metadata row, as the receiver persisted it from the
    /// FileHeader (control plane). `completed_at` is `None` until the byte stream
    /// assembles — which a pure harness run never does (no WebRTC), so this reads
    /// the CONTROL state: a pending download the UI would show as "downloading".
    pub(crate) fn file_meta(&self, file_id: &str) -> Option<crate::storage::messages::StoredFile> {
        self.store().get_file_metadata(file_id).ok().flatten()
    }

    /// File ids referenced by messages that have no completed file row — i.e. the
    /// files the node still needs to RequestFile for (the "needs download" set).
    pub(crate) fn missing_file_ids(&self) -> Vec<String> {
        let mut v = self.store().get_missing_file_ids().unwrap_or_default();
        v.sort();
        v
    }

    // --- Presence (UI layer, read from the authoritative relay) ------------

    /// The set of master identities this node would show as ONLINE (online dots /
    /// Home column). Collapses the relay's online device set through the resolver,
    /// mirroring `onlineIdentitiesProvider`.
    pub(crate) fn online_identities(&self, relay: &MockRelay) -> std::collections::HashSet<String> {
        online_identities_from(relay)
    }

    /// Whether `master` is online (the green dot), the way `identityIsOnline` does
    /// it — true if ANY of that identity's devices has a live socket.
    pub(crate) fn is_online(&self, master: &str, relay: &MockRelay) -> bool {
        online_identities_from(relay).contains(&super::resolver::resolve(master))
    }
}

/// Collapse the relay's online DEVICE set to the set of online MASTER identities
/// (the resolver-collapse the UI's presence layer performs).
fn online_identities_from(relay: &MockRelay) -> std::collections::HashSet<String> {
    relay
        .online_devices()
        .iter()
        .map(|dev| super::resolver::resolve(dev))
        .collect()
}

/// Derive the SQLCipher passphrase the same way `start_node` does
/// (`hex(proto[..32])` of the master keypair).
fn passphrase_for(master: &NativeKeypair) -> String {
    let proto = master.to_protobuf_encoding().expect("encode keypair");
    hex::encode(&proto[..32.min(proto.len())])
}

/// Make a deterministic 32-byte secret from a small seed (test reproducibility;
/// `Math.random`/time are unavailable and we want stable peer_ids per run).
fn seed_bytes(tag: u8) -> [u8; 32] {
    let mut b = [0u8; 32];
    b[0] = tag;
    // Spread the tag a little so distinct tags yield well-separated keys.
    for (i, slot) in b.iter_mut().enumerate() {
        *slot = tag.wrapping_add(i as u8).wrapping_mul(31).wrapping_add(7);
    }
    b
}

/// Spawn one node with the given master + device secret tags, wired into the
/// relay. A shared `master_tag` makes siblings; a distinct `device_tag` gives each
/// its own transport id. Friendless scenarios only.
#[allow(dead_code)]
async fn spawn_node_on(relay: &MockRelay, master_tag: u8, device_tag: u8) -> TestNode {
    spawn_node_with_friends(relay, master_tag, device_tag, &[]).await
}

/// Like `spawn_node_on` but pre-seeds ACCEPTED friendships into the node's DB
/// BEFORE it registers with the relay, so the node's very first `Connected`
/// auto-joins the shared DM rooms (no offline/online thrash needed). Pass each
/// friend's MASTER id.
async fn spawn_node_with_friends(
    relay: &MockRelay,
    master_tag: u8,
    device_tag: u8,
    friend_masters: &[&str],
) -> TestNode {
    spawn_node_full(relay, master_tag, device_tag, friend_masters, None).await
}

/// Full spawn with an optional pre-seeded roster (Step 9C/C5): the devices tagged in
/// `pre_seed_self_devices` hold legacy seats, and a running device the list does not
/// name holds a vouch from the first one, as a link from that device would leave it.
/// Startup then reads it, mimicking a freshly LINKED sibling's imported database.
async fn spawn_node_full(
    relay: &MockRelay,
    master_tag: u8,
    device_tag: u8,
    friend_masters: &[&str],
    pre_seed_self_devices: Option<&[u8]>,
) -> TestNode {
    let roster = pre_seed_self_devices.map(|tags| {
        let linked = (!tags.contains(&device_tag)).then_some(device_tag);
        legacy_roster(master_tag, tags, linked)
    });
    spawn_node_seeded(relay, master_tag, device_tag, friend_masters, roster).await
}

/// Spawn with `roster` merged into the node's own before it starts, as an imported
/// database would hold it.
async fn spawn_node_seeded(
    relay: &MockRelay,
    master_tag: u8,
    device_tag: u8,
    friend_masters: &[&str],
    roster: Option<crate::identity::roster::Roster>,
) -> TestNode {
    let master = NativeKeypair::from_secret_bytes(&seed_bytes(master_tag));
    let device_id = NativeKeypair::from_secret_bytes(&seed_bytes(device_tag)).peer_id();
    let master_id = master.peer_id();
    spawn_node_staged(relay, master, device_tag, friend_masters, |store| {
        // Pre-seed our roster (C5: simulate the imported source database).
        if let Some(roster) = &roster {
            super::roster_book::merge_for_test(store, roster, &master_id, &device_id);
        }
    })
    .await
}

/// Spawn under any master key (one a phrase derives, say), with `stage` writing to
/// the node's database before it starts.
async fn spawn_node_staged(
    relay: &MockRelay,
    master: NativeKeypair,
    device_tag: u8,
    friend_masters: &[&str],
    stage: impl FnOnce(&crate::storage::MessageStore),
) -> TestNode {
    let device = NativeKeypair::from_secret_bytes(&seed_bytes(device_tag));
    let passphrase = passphrase_for(&master);

    let tmp = crate::test_tmp::tempdir().expect("tempdir");
    let db_path = tmp.path().join("messages.db").to_str().unwrap().to_string();

    // Mirror production `start_node`: run the one-time storage-hygiene migration in
    // the single-connection window BEFORE any store/actor opens. (In production
    // this runs in `api::network::start_node`; the harness uses `spawn_node_mock`
    // which bypasses that path, so do it here for parity + to exercise the code.)
    crate::storage::MessageStore::migrate_auto_vacuum_once(&db_path, &passphrase)
        .expect("auto_vacuum migration");

    // Fresh Olm account + seeded friendships persisted to this node's DB BEFORE
    // the node connects (mirrors start_node loading an existing DB).
    let olm = {
        let store = crate::storage::MessageStore::open(&db_path, &passphrase).expect("open store");
        let mgr = OlmManager::new();
        let pickle = mgr.account_pickle_json().expect("pickle");
        store.save_olm_account(&pickle).expect("save olm");
        for fm in friend_masters {
            store.save_friend(fm, "accepted", "outgoing", 0).expect("seed friend");
        }
        stage(&store);
        mgr
    };
    let crypto_store = CryptoStore::open(db_path.clone(), passphrase.clone()).expect("crypto store");
    let crdt_store = CrdtStore::open(db_path.clone(), passphrase.clone()).expect("crdt store");

    let (event_tx, event_rx) = mpsc::channel::<NetworkEvent>(256);
    let (cmd_tx, cmd_rx) = mpsc::channel::<NodeCommand>(256);
    let cmd_tx_clone = cmd_tx.clone();

    let (master_id, join, ws_cmd_rx, ws_event_tx) = super::swarm::spawn_node_mock(
        master.clone(),
        device.clone(),
        event_tx,
        cmd_rx,
        cmd_tx_clone,
        olm,
        crypto_store,
        crdt_store,
        false,
        db_path.clone(),
        passphrase.clone(),
    )
    .await
    .expect("spawn_node_mock");

    let device_id = device.peer_id();
    relay.register_key(&device);
    relay.register(device_id.clone(), ws_cmd_rx, ws_event_tx);

    TestNode {
        master_id,
        device_id,
        cmd_tx,
        event_rx,
        data_root: tmp.path().to_path_buf(),
        db_path,
        passphrase,
        master_kp: master.clone(),
        _join: AbortOnDrop(join),
        _tmp: tmp,
    }
}

/// Spawn a node on a db_path the CALLER already created, pre-seeded and owns.
/// Unlike `spawn_node_full` this neither creates nor seeds the DB, so a test can
/// stage arbitrary on-disk state and run the real startup code against it. The
/// caller must already have run `migrate_auto_vacuum_once` and saved an account.
async fn spawn_node_on_db(
    relay: &MockRelay,
    master_tag: u8,
    device_tag: u8,
    db_path: &str,
    tmp: crate::test_tmp::TestDir,
) -> TestNode {
    let master = NativeKeypair::from_secret_bytes(&seed_bytes(master_tag));
    let device = NativeKeypair::from_secret_bytes(&seed_bytes(device_tag));
    let passphrase = passphrase_for(&master);
    let db_path = db_path.to_string();

    // LOAD the Olm account the way production does: the pickled account plus every
    // stored session and read mark. Minting a fresh account on a DB that already has one
    // hands the node a NEW identity key, so every peer's session silently stops
    // decrypting and a restart test would be measuring the harness rather than the code.
    let olm = {
        let store = crate::storage::MessageStore::open(&db_path, &passphrase).expect("open store");
        match OlmManager::load(&store).expect("restore olm") {
            Some(olm) => olm,
            None => {
                let mgr = OlmManager::new();
                let pickle = mgr.account_pickle_json().expect("pickle");
                store.save_olm_account(&pickle).expect("save olm");
                mgr
            }
        }
    };
    let crypto_store = CryptoStore::open(db_path.clone(), passphrase.clone()).expect("crypto store");
    let crdt_store = CrdtStore::open(db_path.clone(), passphrase.clone()).expect("crdt store");

    let (event_tx, event_rx) = mpsc::channel::<NetworkEvent>(256);
    let (cmd_tx, cmd_rx) = mpsc::channel::<NodeCommand>(256);
    let cmd_tx_clone = cmd_tx.clone();

    let (master_id, join, ws_cmd_rx, ws_event_tx) = super::swarm::spawn_node_mock(
        master.clone(),
        device.clone(),
        event_tx,
        cmd_rx,
        cmd_tx_clone,
        olm,
        crypto_store,
        crdt_store,
        false,
        db_path.clone(),
        passphrase.clone(),
    )
    .await
    .expect("spawn_node_mock");

    let device_id = device.peer_id();
    relay.register_key(&device);
    relay.register(device_id.clone(), ws_cmd_rx, ws_event_tx);

    TestNode {
        master_id,
        device_id,
        cmd_tx,
        event_rx,
        data_root: tmp.path().to_path_buf(),
        db_path,
        passphrase,
        master_kp: master.clone(),
        _join: AbortOnDrop(join),
        _tmp: tmp,
    }
}

/// Restart one node: take it off the relay, kill its event loop, and boot a new
/// one on the SAME encrypted DB with the same master/device keys.
///
/// MLS state is the interesting half: the storage blob carrying the private half
/// of every minted KeyPackage is restored from the crypto store, so anything
/// minted but not persisted is gone. The returned `event_rx` is fresh.
async fn restart_node(
    relay: &MockRelay,
    node: TestNode,
    master_tag: u8,
    device_tag: u8,
) -> TestNode {
    restart_node_with(relay, node, master_tag, device_tag, |_, _| {}).await
}

/// [`restart_node`] that changes the stopped node's DB before it boots again, as a
/// backup put back would: `stage` gets the DB path and passphrase.
async fn restart_node_with(
    relay: &MockRelay,
    node: TestNode,
    master_tag: u8,
    device_tag: u8,
    stage: impl FnOnce(&str, &str),
) -> TestNode {
    let device_id = node.device_id.clone();
    let passphrase = node.passphrase.clone();
    relay.set_online(&device_id, false);
    assert!(
        wait_until(10, async || !relay.online_devices().contains(&device_id)).await,
        "{device_id} must be off the relay before its DB is reopened",
    );
    let (db_path, tmp) = node.into_storage();
    // The old loop is aborted, so its store actors are closing. Give the
    // SQLCipher handles a moment to go: there is no signal to poll for "a task
    // that was aborted has finished dropping its locals", and reopening the
    // file under the old writer costs a 4s busy_timeout on every query.
    sleep_ms(300).await;
    stage(&db_path, &passphrase);
    spawn_node_on_db(relay, master_tag, device_tag, &db_path, tmp).await
}

/// Drain a node's events until `pred` returns true or the timeout elapses.
/// Returns true if matched.
async fn wait_event(
    node: &mut TestNode,
    timeout: std::time::Duration,
    mut pred: impl FnMut(&NetworkEvent) -> bool,
) -> bool {
    let deadline = tokio::time::Instant::now() + timeout;
    loop {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        if remaining.is_zero() {
            return false;
        }
        match tokio::time::timeout(remaining, node.event_rx.recv()).await {
            Ok(Some(ev)) => {
                if pred(&ev) {
                    return true;
                }
            }
            _ => return false,
        }
    }
}

/// Drain any currently-queued events without blocking (clears the channel).
fn drain_events(node: &mut TestNode) {
    while node.event_rx.try_recv().is_ok() {}
}

async fn sleep_ms(ms: u64) {
    tokio::time::sleep(std::time::Duration::from_millis(ms)).await;
}

/// Poll `cond` until it holds, or `secs` elapse. Returns whether it held.
///
/// **This is the default settle primitive, not `sleep_ms`.** A fixed sleep must be
/// long enough for the slowest machine that will ever run it, so it is dead time
/// everywhere else and a silent flake where it turned out too short. Reach for
/// `sleep_ms` ONLY to prove an ABSENCE, which has no state to poll.
///
/// POLL LIVE STATE, NEVER A RUNNING NODE'S DB. `olm_status`, `mls_members` and
/// `mls_epoch` round-trip a `DebugSnapshot` and are free to ask repeatedly.
/// Everything else here calls `store()`, which opens a NEW SQLCipher connection
/// and starves the node's own writer (busy_timeout 4000ms): a 250ms poll for a
/// channel-row heal stopped it landing inside 15s where a sleep saw it in under 4.
/// If the only settle signal is on disk, use a sleep and say why.
async fn wait_until(secs: u64, mut cond: impl AsyncFnMut() -> bool) -> bool {
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(secs);
    // Backs off 25ms -> 250ms. Some predicates here open SQLCipher, whose key
    // derivation is deliberately expensive, so a flat 25ms poll would spend more
    // CPU on the KDF than the thing being waited for.
    let mut interval = 25;
    loop {
        if cond().await {
            return true;
        }
        if tokio::time::Instant::now() >= deadline {
            return false;
        }
        sleep_ms(interval).await;
        interval = (interval * 2).min(250);
    }
}

/// Sleep until a wall-clock DEADLINE (plus `grace_ms`), not for a duration.
///
/// Use this wherever a test must outlast a real timestamp: a grant expiry, a TTL,
/// a sweep window. The duration form silently depends on how long the steps above
/// took, which breaks the moment those steps start polling instead of sleeping.
async fn sleep_until_ms(deadline_ms: u64, grace_ms: u64) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64;
    sleep_ms(deadline_ms.saturating_sub(now) + grace_ms).await;
}

/// Wait until `a` and `b` hold a CONFIRMED Olm session with each other, and panic
/// with both directions' status if they do not. Bidirectional on purpose: an
/// outbound-only session is not usable yet, which is exactly the half-built state
/// a too-short fixed sleep left behind.
async fn expect_olm_confirmed(a: &TestNode, b: &TestNode, secs: u64) {
    let ok = wait_until(secs, async || {
        a.olm_status(&b.device_id).await == "confirmed"
            && b.olm_status(&a.device_id).await == "confirmed"
    })
    .await;
    assert!(
        ok,
        "Olm never confirmed both ways within {}s: {} -> {} is {:?}, {} -> {} is {:?}",
        secs,
        a.device_id,
        b.device_id,
        a.olm_status(&b.device_id).await,
        b.device_id,
        a.device_id,
        b.olm_status(&a.device_id).await,
    );
}

/// Wait until a freshly spawned friend PAIR is actually usable: confirmed Olm both
/// ways, AND both devices present in the DM room their traffic rides.
///
/// Waiting only for Olm is not enough: the session confirms well before both nodes
/// finish joining their rooms, and tests converted to Olm-only went intermittent
/// by sending into a room the recipient had not joined yet.
async fn expect_dm_pair_ready(relay: &MockRelay, a: &TestNode, b: &TestNode, secs: u64) {
    expect_olm_confirmed(a, b, secs).await;
    let room = super::types::dm_room_code(&a.master_id, &b.master_id);
    let ok = wait_until(secs, async || {
        let members = relay.room_devices(&room);
        members.contains(&a.device_id) && members.contains(&b.device_id)
    })
    .await;
    assert!(
        ok,
        "{} and {} never both joined DM room {} within {}s, got {:?}",
        a.device_id,
        b.device_id,
        room,
        secs,
        relay.room_devices(&room),
    );
}

/// Two devices of ONE master are ready to sync once their Olm session is confirmed
/// and both sit in the master's inbox room, which is the room sibling traffic rides
/// when the master has no friends and so no DM room.
async fn expect_siblings_ready(relay: &MockRelay, a: &TestNode, b: &TestNode, secs: u64) {
    expect_olm_confirmed(a, b, secs).await;
    let room = format!("inbox:{}", a.master_id);
    let ok = wait_until(secs, async || {
        let members = relay.room_devices(&room);
        members.contains(&a.device_id) && members.contains(&b.device_id)
    })
    .await;
    assert!(
        ok,
        "siblings {} and {} never both joined {} within {}s, got {:?}",
        a.device_id,
        b.device_id,
        room,
        secs,
        relay.room_devices(&room),
    );
}

/// Wait until `holder`'s MLS group for `group_id` carries `leaf`'s device, and
/// panic with the leaf list if it never does. `group_id` is a `server_id`, or
/// `subgroup_id(server, channel)` for a per-channel group.
async fn expect_mls_leaf(holder: &TestNode, group_id: &str, leaf: &str, secs: u64) {
    let ok = wait_until(secs, async || {
        holder.mls_members(group_id).await.iter().any(|m| m == leaf)
    })
    .await;
    assert!(
        ok,
        "MLS group {} on {} never gained leaf {} within {}s, got {:?}",
        group_id,
        holder.device_id,
        leaf,
        secs,
        holder.mls_members(group_id).await,
    );
}

/// Wait until `holder`'s MLS group for `group_id` no longer carries `leaf`. An
/// eviction is a convergence, not an absence: the leaf is gone once the commit
/// that removed it has been applied, which is observable, so it is polled.
async fn expect_no_mls_leaf(holder: &TestNode, group_id: &str, leaf: &str, secs: u64) {
    let ok = wait_until(secs, async || {
        // Some(..) required: a snapshot that never came back is not an eviction.
        matches!(holder.mls_members_checked(group_id).await, Some(v) if !v.iter().any(|m| m == leaf))
    })
    .await;
    assert!(
        ok,
        "MLS group {} on {} never dropped leaf {} within {}s, got {:?}",
        group_id,
        holder.device_id,
        leaf,
        secs,
        holder.mls_members(group_id).await,
    );
}

async fn expect_mls_group(nodes: &[&TestNode], group_id: &str, secs: u64) {
    for holder in nodes {
        for leaf in nodes {
            expect_mls_leaf(holder, group_id, &leaf.device_id, secs).await;
        }
    }
}

/// Drive `CreateServer` on `node` and return the new `server_id` (captured from
/// the `ServerCreated` event the owner emits). The default `#general` channel id
/// is `format!("{}-general", &server_id[..8])`.
async fn create_server_and_wait(node: &mut TestNode, name: &str) -> String {
    node.cmd_tx
        .send(NodeCommand::CreateServer { name: name.to_string() })
        .await
        .unwrap();
    let mut server_id = None;
    let ok = wait_event(node, std::time::Duration::from_secs(15), |ev| {
        if let NetworkEvent::ServerCreated { server_id: sid, .. } = ev {
            server_id = Some(sid.clone());
            true
        } else {
            false
        }
    })
    .await;
    assert!(ok, "owner should emit ServerCreated");
    let server_id = server_id.expect("ServerCreated carried a server_id");
    let secret = node.live_server_state(&server_id).await.and_then(|s| s.join_secret());
    JOIN_SECRETS.lock().unwrap().insert(server_id.clone(), *secret.expect("a new server has its join key"));
    SERVER_OWNERS.lock().unwrap().insert(server_id.clone(), node.master_id.clone());
    // No one can ask to join before the owner's first lock is on the relay and in the state.
    assert!(
        wait_until(15, async || node.live_server_state(&server_id).await.is_some_and(|s| s.join_lock.has_lock())).await,
        "the owner makes the server's first join lock",
    );
    server_id
}

/// The owner of every server the harness created: the relay keys a lock chain by it.
static SERVER_OWNERS: std::sync::LazyLock<Mutex<HashMap<String, String>>> =
    std::sync::LazyLock::new(|| Mutex::new(HashMap::new()));

fn owner_of(server_id: &str) -> String {
    SERVER_OWNERS.lock().unwrap().get(server_id).cloned().unwrap_or_default()
}

/// The newest join lock the relay shows for a harness-created server.
fn relay_tip(relay: &MockRelay, server_id: &str) -> super::join_lock::LockLink {
    relay.lock_chain(server_id, &owner_of(server_id)).last().cloned().expect("the server's join lock is on the relay")
}

/// The join secret of every server the harness created: what its members hold.
static JOIN_SECRETS: std::sync::LazyLock<Mutex<HashMap<String, [u8; 32]>>> =
    std::sync::LazyLock::new(|| Mutex::new(HashMap::new()));

fn join_secret_of(server_id: &str) -> Option<[u8; 32]> {
    JOIN_SECRETS.lock().unwrap().get(server_id).copied()
}

/// The `key=` an invite to `server_id` carries: what every harness join passes, as a
/// user's click on the link would.
fn invite_key(server_id: &str) -> Option<String> {
    let secret = join_secret_of(server_id)?;
    Some(super::sealed_box::key_to_text(&super::sealed_box::public_of(&secret)))
}

/// The invite key a node would put in a link it makes now.
async fn live_join_key(node: &TestNode, server_id: &str) -> Option<String> {
    node.live_server_state(server_id).await.and_then(|s| s.join_public_text())
}

/// `kp`'s signed ask to join `server_id`, as a real joiner's request carries it.
fn join_ask(server_id: &str, at: i64, kp: &NativeKeypair) -> Option<crate::crdt::operations::JoinAsk> {
    Some(crate::crdt::operations::JoinAsk::sign(server_id, at, kp))
}

/// A reply key for a hand-built join request.
fn fresh_reply_key() -> String {
    super::sealed_box::key_to_text(&super::sealed_box::public_of(&super::sealed_box::new_secret().unwrap()))
}

/// `msg` sealed to a server's current door and invite key as `device` would send it,
/// which is what an invite holder can write and nothing else can.
fn sealed_to_members(relay: &MockRelay, server_id: &str, device: &str, msg: &super::types::HavenMessage) -> Vec<u8> {
    let invite = super::sealed_box::public_of(&join_secret_of(server_id).expect("a harness-created server"));
    let tip = relay_tip(relay, server_id);
    super::join_lane::seal_to_members(&tip.door_key().unwrap(), &invite, tip.n, server_id, device, msg).expect("seals")
}

/// The default `#general` channel id for a server.
fn general_channel_of(server_id: &str) -> String {
    format!("{}-general", &server_id[..8.min(server_id.len())])
}

/// Build a CRDT op by hand the way `create_op` would, signed with `signer` or left
/// unsigned when it is `None`.
///
/// `author` is written VERBATIM, which is the point: the interesting cases are an
/// author the signing key does not derive, and no signature at all. `ahead_ms`
/// offsets the timestamp so an op that WOULD win the LWW comparison can be built.
fn forge_crdt_op(
    server_id: &str,
    author: &str,
    payload: crate::crdt::operations::CrdtPayload,
    ahead_ms: u64,
    signer: Option<&NativeKeypair>,
) -> crate::crdt::operations::CrdtOp {
    use base64::Engine as _;
    let mut op = crate::crdt::operations::CrdtOp {
        server_id: server_id.to_string(),
        hlc: crate::crdt::hlc::HlcTimestamp {
            physical_ms: crate::crdt::hlc::wall_clock_ms().saturating_add(ahead_ms),
            counter: 0,
            actor: author.to_string(),
        },
        author: author.to_string(),
        payload,
        auth: None,
    };
    if let Some(kp) = signer {
        let pk = base64::engine::general_purpose::STANDARD.encode(kp.public_key_protobuf());
        op.sign(kp, &pk);
    }
    op
}

/// The exact bytes a peer would put on the wire to replicate one op.
fn crdt_broadcast_frame(server_id: &str, op: &crate::crdt::operations::CrdtOp) -> Vec<u8> {
    serde_json::to_vec(&super::types::HavenMessage::CrdtOpBroadcast {
        server_id: server_id.to_string(),
        op_json: serde_json::to_string(op).expect("serialize op"),
    })
    .expect("serialize frame")
}

/// Have `from` carry `msg` to `to` inside its own Olm session: what a member with a
/// modified client can send, and the only way an Olm-lane message reaches anyone.
async fn carry_as(from: &TestNode, to: &TestNode, msg: super::types::HavenMessage) {
    from.cmd_tx
        .send(NodeCommand::TestCarry { device: to.device_id.clone(), msg: Box::new(msg) })
        .await
        .unwrap();
}

/// Have `from` send `msg` to `to` the way its lane allows: inside `from`'s own Olm
/// session, or sealed into `room` for a relay-lane message. What a peer with a
/// modified client can send, so a test reaches the gates past the transport.
async fn send_as(relay: &MockRelay, room: &str, from: &TestNode, to: &TestNode, msg: super::types::HavenMessage) {
    if msg.lane() == super::types::Lane::Relay {
        relay.inject(room, &from.device_id, &to.device_id, serde_json::to_vec(&msg).unwrap());
    } else {
        carry_as(from, to, msg).await;
    }
}

/// The op broadcast a member hands on.
fn crdt_broadcast(server_id: &str, op: &crate::crdt::operations::CrdtOp) -> super::types::HavenMessage {
    super::types::HavenMessage::CrdtOpBroadcast {
        server_id: server_id.to_string(),
        op_json: serde_json::to_string(op).expect("serialize op"),
    }
}

/// A sync answer carrying a batch of ops.
fn sync_response(server_id: &str, ops: &[crate::crdt::operations::CrdtOp]) -> super::types::HavenMessage {
    super::types::HavenMessage::SyncResponse {
        server_id: server_id.to_string(),
        ops_json: serde_json::to_string(ops).expect("serialize ops"),
        nonce: None,
    }
}

/// `msg` sealed to the reply key of `joiner`'s pending join, as `from_device` would
/// answer it: what a member that opened the request can write to the joiner.
async fn sealed_to_joiner(relay: &MockRelay, joiner: &TestNode, server_id: &str, from_device: &str, msg: &super::types::HavenMessage) -> Vec<u8> {
    let reply_key = || {
        joiner.store().load_pending_joins().ok()?.into_iter()
            .find(|row| row.server_id == server_id)?
            .reply_secret.as_deref()
            .and_then(super::join_lane::ReplySecret::from_stored)
            .map(|r| r.public_text())
    };
    assert!(wait_until(10, async || reply_key().is_some()).await, "the joiner's pending row holds its reply key");
    let key = super::sealed_box::key_from_text(&reply_key().unwrap()).unwrap();
    let tip = relay_tip(relay, server_id);
    let door = super::join_lock::test_door_secret(&tip.door).expect("a door this process made");
    super::join_lane::seal_to_joiner(&key, &door, tip.n, server_id, from_device, &joiner.device_id, msg).expect("seals")
}

/// A legacy roster for `master_tag`: every tagged device claimed by the master and
/// consenting, plus `linked` vouched for by the first of them.
fn legacy_roster(master_tag: u8, device_tags: &[u8], linked: Option<u8>) -> crate::identity::roster::Roster {
    use crate::identity::roster;
    let master = NativeKeypair::from_secret_bytes(&seed_bytes(master_tag));
    let devices: Vec<NativeKeypair> =
        device_tags.iter().map(|t| NativeKeypair::from_secret_bytes(&seed_bytes(*t))).collect();
    let mut r = roster::Roster::legacy_for_test(&master, &devices.iter().collect::<Vec<_>>());
    if let (Some(tag), Some(voucher)) = (linked, devices.first()) {
        let new = NativeKeypair::from_secret_bytes(&seed_bytes(tag));
        r.add_consent(roster::sign_consent(&new, &master.peer_id()));
        r.add_vouch(roster::sign_vouch(voucher, &master.peer_id(), roster::LEGACY_BASE, &new.peer_id()));
    }
    r
}

/// Merge a legacy roster naming the tagged devices into the node's own roster, the
/// state two siblings reach once they have met. `master_tag` is the shared sibling
/// master seed tag; `device_tag` is the node the DB belongs to.
fn seed_device_list_into_db(db_path: &str, passphrase: &str, master_tag: u8, device_tags: &[u8]) {
    let master = NativeKeypair::from_secret_bytes(&seed_bytes(master_tag)).peer_id();
    let store = crate::storage::MessageStore::open(db_path, passphrase).expect("open store");
    let roster = legacy_roster(master_tag, device_tags, None);
    super::roster_book::merge_for_test(&store, &roster, &master, "");
}

// ---------------------------------------------------------------------------
// The proof-of-concept test: peer-fallback recovers your OWN stranded sends
// on the CORRECT side (the inversion regression from the 2026-06-18 session).
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
// The harness guard is a `std::sync::MutexGuard` deliberately held across the
// whole async test: it serializes harness tests against the process-global
// resolver. An async-aware mutex would let two harness tests interleave and
// corrupt each other's resolver state — exactly what the guard prevents.
#[allow(clippy::await_holding_lock)]
async fn peer_fallback_recovers_own_sends_correct_direction() {
    let _g = test_guard();
    // Point the process-global `data_dir()` at a throwaway temp dir so any stray
    // global-data-dir code path (vault/files/etc.) can't touch the developer's
    // REAL ~/.hollow DB (wrong passphrase → SQLCipher hmac failures). Each node
    // still uses its own injected per-node db_path for messages.
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    // SAFETY: set at the very start of this serialized test (HARNESS_GUARD); no
    // other thread reads the env concurrently here.
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();

    // A = friend (outsider, device == master, the keystone case). M = our identity
    // with two devices B and C; C sends while B is offline, and B must later recover
    // those sends from A on the correct side.
    const A_MASTER: u8 = 10;
    const M_MASTER: u8 = 20;
    const B_DEV: u8 = 21;
    const C_DEV: u8 = 22;

    // Compute the master ids up front (deterministic from the seed tags) so each
    // node can be spawned with its friendship ALREADY seeded — its first
    // Connected then auto-joins the shared DM room (no offline/online thrash).
    let a_master = NativeKeypair::from_secret_bytes(&seed_bytes(A_MASTER)).peer_id();
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();

    // Seed the (process-global) resolver BEFORE spawning so every node collapses
    // both M device ids to the master, A routes M→devices, and B knows it is
    // multi-device (`devices_for(M)` non-empty => sets both_directions).
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev.clone(), c_dev.clone()]);

    // Stagger spawns so each node's pairwise Olm key exchange settles before the
    // next joins — avoids the symmetric KeyBundle glare (all-online-at-once makes
    // every pair defer waiting for the other, which only the 30s sweep breaks).
    let mut a = spawn_node_with_friends(&relay, A_MASTER, A_MASTER, &[&m_master]).await;
    sleep_ms(1500).await;
    let mut c = spawn_node_with_friends(&relay, M_MASTER, C_DEV, &[&a_master]).await;
    sleep_ms(1500).await;
    let mut b = spawn_node_with_friends(&relay, M_MASTER, B_DEV, &[&a_master]).await;

    // Olm key exchange must FULLY CONFIRM before any DM is sent, or the DM rides an
    // unconfirmed ratchet and fails to decrypt. Glare resolution takes a couple of
    // round trips, so wait for the sessions rather than guessing at a duration.
    expect_dm_pair_ready(&relay, &a, &b, 20).await;
    expect_dm_pair_ready(&relay, &a, &c, 20).await;
    drain_events(&mut a);
    drain_events(&mut b);
    drain_events(&mut c);

    // --- B goes offline; C and A exchange 6 DMs (C wrote FIRST) ---
    relay.set_online(&b.device_id, false);
    sleep_ms(300).await;

    for (i, mid) in ["c1", "c2", "c3"].iter().enumerate() {
        c.cmd_tx
            .send(NodeCommand::SendMessage {
                peer_id: a.master_id.clone(),
                text: format!("from-C-{}", i + 1),
                message_id: (*mid).to_string(),
                reply_to_mid: None,
                link_preview: None,
            })
            .await
            .unwrap();
        sleep_ms(60).await; // keep timestamps strictly ordered + ratchet settling
    }
    for (i, mid) in ["a1", "a2", "a3"].iter().enumerate() {
        a.cmd_tx
            .send(NodeCommand::SendMessage {
                peer_id: b.master_id.clone(),
                text: format!("from-A-{}", i + 1),
                message_id: (*mid).to_string(),
                reply_to_mid: None,
                link_preview: None,
            })
            .await
            .unwrap();
        sleep_ms(60).await;
    }

    // Let A persist everything (A is the holder of the full conversation).
    // Generous: the first sends had no Olm session, so they queue in
    // pending_messages and re-deliver after KeyRequest→KeyBundle settles.
    sleep_ms(2500).await;

    {
        let thread = a.dm_thread(&b.master_id);
        assert_eq!(thread.len(), 6, "A should hold all 6 messages, got {}", thread.len());
    }

    assert!(
        a.is_online(&m_master, &relay),
        "A should see our identity M online while a device is connected"
    );
    assert!(
        b.online_identities(&relay).contains(&a.master_id),
        "B should see friend A among online identities"
    );

    // --- C goes offline; B comes online and must recover from A ---
    relay.set_online(&c.device_id, false);
    sleep_ms(100).await;
    drain_events(&mut b);
    relay.set_online(&b.device_id, true);

    let synced = wait_event(&mut b, std::time::Duration::from_secs(5), |ev| {
        matches!(ev, NetworkEvent::DmSyncCompleted { .. })
    })
    .await;
    assert!(synced, "B should receive DmSyncCompleted from A");
    sleep_ms(200).await; // let the final inserts commit

    // --- THE ASSERTIONS: B recovered all 6 on the CORRECT side ---
    let thread = b.dm_thread(&a.master_id);
    let by_text: HashMap<String, bool> =
        thread.iter().map(|m| (m.text.clone(), m.is_mine)).collect();

    // Our own sends (made on sibling C) MUST be is_mine=true on B — the
    // inversion: A stored them is_mine=0, B re-orients to is_mine=true.
    for t in ["from-C-1", "from-C-2", "from-C-3"] {
        assert_eq!(
            by_text.get(t),
            Some(&true),
            "our own send {t:?} must land as is_mine=true on B (inversion). Got map: {by_text:?}"
        );
    }
    for t in ["from-A-1", "from-A-2", "from-A-3"] {
        assert_eq!(
            by_text.get(t),
            Some(&false),
            "friend send {t:?} must land as is_mine=false on B. Got map: {by_text:?}"
        );
    }
    assert_eq!(thread.len(), 6, "B must have all 6 messages, got {}", thread.len());

    // Every recovered message must carry a signature (the "Unsigned" tag must not
    // appear) — a backfill that mis-oriented direction also breaks sig context.
    assert!(
        thread.iter().all(|m| m.has_sig),
        "every backfilled DM must be signed (no Unsigned bubbles)"
    );

    let earliest = thread
        .iter()
        .min_by_key(|m| m.timestamp)
        .expect("at least one message");
    assert!(
        earliest.is_mine && earliest.text.starts_with("from-C"),
        "earliest message must be our own C-send (correct order), got {:?}",
        earliest.text
    );
}

// Rung 2: a friend JOINS a server, the MLS group forms across both nodes, and an
// encrypted channel message DECRYPTS on the joiner's device.

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests; see other test
async fn server_join_forms_mls_and_channel_message_decrypts() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();

    // O = owner (single device), J = joiner (single device). Both plain
    // single-device identities (device == master) — the common case.
    const O_MASTER: u8 = 30;
    const J_MASTER: u8 = 40;
    let o_master = NativeKeypair::from_secret_bytes(&seed_bytes(O_MASTER)).peer_id();
    let j_master = NativeKeypair::from_secret_bytes(&seed_bytes(J_MASTER)).peer_id();

    // Befriend O <-> J (so Olm key exchange + presence work as in production;
    // server join needs a live Olm session for the direct handshake messages).
    let mut o = spawn_node_with_friends(&relay, O_MASTER, O_MASTER, &[&j_master]).await;
    sleep_ms(1500).await;
    let mut j = spawn_node_with_friends(&relay, J_MASTER, J_MASTER, &[&o_master]).await;
    expect_dm_pair_ready(&relay, &o, &j, 15).await;

    // --- Owner creates a server (+ implicit #general channel) ---
    let server_id = create_server_and_wait(&mut o, "Test Server").await;
    let general = general_channel_of(&server_id);
    sleep_ms(300).await;

    assert_eq!(
        o.mls_members(&server_id).await,
        vec![o.device_id.clone()],
        "owner is the sole MLS leaf right after CreateServer"
    );
    drain_events(&mut o);
    drain_events(&mut j);

    j.cmd_tx
        .send(NodeCommand::JoinServer { server_id: server_id.clone(), twitch_proof_json: None, nsfw_confirmed: false, owner_pin: None, join_key: invite_key(&server_id) })
        .await
        .unwrap();

    let joined = wait_event(&mut j, std::time::Duration::from_secs(8), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(joined, "joiner should emit ServerJoined");

    // …then the MLS handshake (KeyPackage → 2s batch timer → Welcome) forms the
    // group on the joiner. Give the 2s mls_batch_timer room to fire after the KP.
    sleep_ms(5000).await;

    let owner_leaves = o.mls_members(&server_id).await;
    let joiner_leaves = j.mls_members(&server_id).await;
    let expected = {
        let mut v = vec![o.device_id.clone(), j.device_id.clone()];
        v.sort();
        v
    };
    assert_eq!(owner_leaves, expected, "owner's MLS group must contain both device leaves");
    assert_eq!(joiner_leaves, expected, "joiner's MLS group must contain both device leaves");
    assert!(o.mls_epoch(&server_id).await.unwrap_or(0) >= 1, "owner epoch advanced past the add");
    assert_eq!(
        o.mls_epoch(&server_id).await,
        j.mls_epoch(&server_id).await,
        "owner and joiner must be at the same MLS epoch"
    );

    let panel = j.member_panel(&server_id, &relay);
    let masters: Vec<String> = panel.iter().map(|r| r.master.clone()).collect();
    assert!(masters.contains(&o_master) && masters.contains(&j_master),
        "joiner's member panel shows both masters, got {masters:?}");
    assert!(panel.iter().all(|r| r.online), "both members online in the panel");
    // Raw layer: CRDT member keys are MASTERS, not device ids (canonicalize_members).
    assert_eq!(j.raw_crdt_member_keys(&server_id), {
        let mut v = vec![o_master.clone(), j_master.clone()]; v.sort(); v
    }, "CRDT members must be master-keyed");

    drain_events(&mut j);

    relay.set_recording(&o.device_id, true);
    o.cmd_tx
        .send(NodeCommand::SendChannelMessage {
            server_id: server_id.clone(),
            channel_id: general.clone(),
            text: "hello channel".to_string(),
            message_id: "ch-msg-1".to_string(),
            reply_to_mid: None,
            link_preview: None,
        })
        .await
        .unwrap();

    let got = wait_event(&mut j, std::time::Duration::from_secs(5), |ev| {
        matches!(ev, NetworkEvent::ChannelMessageReceived { text, .. } if text == "hello channel")
    })
    .await;
    assert!(got, "joiner must receive + decrypt the channel message");
    sleep_ms(200).await;

    let msgs = j.channel_messages(&server_id, &general);
    let row = msgs.iter().find(|m| m.text == "hello channel").expect("message stored");
    assert_eq!(row.sender_master, o_master, "channel message attributed to owner master");
    assert!(!row.is_mine, "received message is not is_mine on the joiner");

    let frame = relay.recorded_frames(&o.device_id).into_iter().find(|frame| {
        matches!(serde_json::from_slice::<super::types::HavenMessage>(super::frame_auth::unchecked_body(frame)),
            Ok(super::types::HavenMessage::MlsChannelMessage { .. }))
    }).expect("recorded MLS ciphertext");
    let epoch = j.mls_epoch(&server_id).await;
    // ABSENCE proof: replays spread over several seconds must not evict anyone, and
    // "nothing happened" has no signal to poll (counted in BUDGET_MS).
    for _ in 0..4 {
        relay.inject(&server_id, &o.device_id, &j.device_id, frame.clone());
        sleep_ms(2100).await;
    }
    assert_eq!(j.mls_epoch(&server_id).await, epoch,
        "replayed consumed generations must not evict a healthy MLS group");
    assert_eq!(o.mls_epoch(&server_id).await, epoch,
        "replays must not make the coordinator remove and re-add a member");
}

// A PUBLIC channel broadcasts signed PLAINTEXT and the relay frame's `from` is the
// sender's DEVICE id, so the receiver must attribute the message to that sender's
// MASTER in BOTH the live event and the raw stored row. A device-keyed row breaks
// the name in the bubble and the signature check alike.

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests; see other test
async fn public_channel_message_from_multidevice_sender_attributes_to_master() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();

    // O = owner/sender, J = joiner. BOTH are real fresh installs (device != master,
    // the shape every fresh friend has since ad7b49e). Resolver NOT pre-seeded —
    // J must learn O's device→master purely from the organic friend handshake, so
    // resolving the relay frame's device `from` to O's master is a real lookup.
    const O_MASTER: u8 = 50;
    const O_DEV: u8 = 51;
    const J_MASTER: u8 = 52;
    const J_DEV: u8 = 53;
    let o_master = NativeKeypair::from_secret_bytes(&seed_bytes(O_MASTER)).peer_id();
    let o_dev = NativeKeypair::from_secret_bytes(&seed_bytes(O_DEV)).peer_id();
    let j_master = NativeKeypair::from_secret_bytes(&seed_bytes(J_MASTER)).peer_id();
    let j_dev = NativeKeypair::from_secret_bytes(&seed_bytes(J_DEV)).peer_id();
    // Precondition: meaningless unless the sender's device != master.
    assert_ne!(o_dev, o_master, "O must be a real fresh install (device != master)");
    assert_ne!(j_dev, j_master, "J must be a real fresh install (device != master)");

    let mut o = spawn_node_with_friends(&relay, O_MASTER, O_DEV, &[]).await;
    let mut j = spawn_node_with_friends(&relay, J_MASTER, J_DEV, &[]).await;
    sleep_ms(1500).await;
    drain_events(&mut o);
    drain_events(&mut j);

    // Organic friend handshake O <-> J (drives the device-list/profile pushes both
    // directions, warming J's resolver with O_DEV → O_MASTER and vice versa).
    o.cmd_tx
        .send(NodeCommand::SendFriendRequest { peer_id: j_master.clone() })
        .await
        .unwrap();
    let j_got_req = wait_event(&mut j, std::time::Duration::from_secs(8), |ev| {
        matches!(ev, NetworkEvent::FriendRequestReceived { .. })
    })
    .await;
    assert!(j_got_req, "J must receive O's friend request");
    j.cmd_tx
        .send(NodeCommand::AcceptFriendRequest { peer_id: o_master.clone() })
        .await
        .unwrap();
    expect_dm_pair_ready(&relay, &o, &j, 15).await;
    // ...and J's resolver has learned O's device -> master mapping, which is
    // the precondition the assertion below states.
    wait_until(15, async || super::resolver::resolve(&o_dev) == o_master).await;
    drain_events(&mut o);
    drain_events(&mut j);

    // Precondition: J's resolver maps O's device → O's master. Without this, the
    // resolve in the PublicChannelMessage handler is a no-op and the test can't
    // distinguish the fix.
    assert_eq!(
        super::resolver::resolve(&o_dev), o_master,
        "J's resolver must map O's device → O's master after the friend handshake"
    );

    // O creates a server (+ implicit #general); J joins (forms the shared room so a
    // SendToRoom public broadcast reaches J).
    let server_id = create_server_and_wait(&mut o, "Public Test Server").await;
    let general = general_channel_of(&server_id);
    sleep_ms(300).await;
    drain_events(&mut o);
    drain_events(&mut j);

    j.cmd_tx
        .send(NodeCommand::JoinServer { server_id: server_id.clone(), twitch_proof_json: None, nsfw_confirmed: false, owner_pin: None, join_key: invite_key(&server_id) })
        .await
        .unwrap();
    let joined = wait_event(&mut j, std::time::Duration::from_secs(8), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(joined, "J must join the server");
    sleep_ms(3000).await; // let membership + the shared server room settle

    o.cmd_tx
        .send(NodeCommand::SetChannelPublic {
            server_id: server_id.clone(),
            channel_id: general.clone(),
            is_public: true,
        })
        .await
        .unwrap();
    sleep_ms(2000).await; // let the ChannelPublicChanged CRDT op converge to J
    drain_events(&mut j);

    // --- THE PAYOFF: O sends a PUBLIC channel message from its DEVICE; J must
    // attribute it to O's MASTER (not O_DEV) ---
    o.cmd_tx
        .send(NodeCommand::SendChannelMessage {
            server_id: server_id.clone(),
            channel_id: general.clone(),
            text: "public from a device".to_string(),
            message_id: "pub-md-1".to_string(),
            reply_to_mid: None,
            link_preview: None,
        })
        .await
        .unwrap();

    // Live event: from_peer is the raw value handle_envelope_channel_message was
    // called with — O's MASTER with the fix, O_DEV without it.
    let attributed_to_master = wait_event(&mut j, std::time::Duration::from_secs(6), |ev| {
        matches!(ev, NetworkEvent::ChannelMessageReceived { text, from_peer, .. }
            if text == "public from a device" && *from_peer == o_master)
    })
    .await;
    assert!(
        attributed_to_master,
        "J must receive the public channel message attributed to O's MASTER ({o_master}), not O's device ({o_dev})"
    );
    sleep_ms(200).await;

    // Raw layer (device-keyed truth): the stored row's sender is O's MASTER. This
    // is the assertion the master-collapsed `channel_messages` inspector can't make
    // — it resolves device→master on read and would pass even on a device-keyed row.
    assert_eq!(
        j.raw_channel_message_sender("pub-md-1").as_deref(),
        Some(o_master.as_str()),
        "the stored public-channel row must be MASTER-keyed (raw), not device-keyed"
    );
    let msgs = j.channel_messages(&server_id, &general);
    let row = msgs.iter().find(|m| m.text == "public from a device").expect("public message stored");
    assert_eq!(row.sender_master, o_master, "public channel message attributed to O's master");
    assert!(!row.is_mine, "received public message is not is_mine on J");
}

