    let mut b = spawn_node_with_friends(&relay, B_MASTER, B_MASTER, &[&a_master]).await;
    expect_dm_pair_ready(&relay, &a, &b, 15).await;
    // The auto-download advert exchange has no live probe (counted in BUDGET_MS).
