// ---------------------------------------------------------------------------
// Claim C-24: what a relay reads. Each test runs a real flow under the wiretap and
// asserts on what reached the relay in a form it can read.
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn c24_the_sibling_lane_rides_olm() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    relay.start_wiretap();

    const F_MASTER: u8 = 60;
    const F_DEV: u8 = 61;
    const M_MASTER: u8 = 62;
    const B_DEV: u8 = 63;
    const C_DEV: u8 = 64;
    let f_master = NativeKeypair::from_secret_bytes(&seed_bytes(F_MASTER)).peer_id();
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev.clone(), c_dev.clone()]);

    let _f = spawn_node_with_friends(&relay, F_MASTER, F_DEV, &[&m_master]).await;
    let mut b = spawn_node_with_friends(&relay, M_MASTER, B_DEV, &[&f_master]).await;
    {
        let store = b.store();
        store.insert(&f_master, "hi", false, 4000, None, None, Some("canary-read-mid"), None, None, None, None).unwrap();
        store.save_setting(&format!("seen:dm:{f_master}"), "canary-read-mid").unwrap();
        store.merge_personal_emote_entry("canaryemote", "", false, "", 10).unwrap();
    }
    sleep_ms(1500).await;
    let mut c = spawn_node_with_friends(&relay, M_MASTER, C_DEV, &[]).await;
    expect_siblings_ready(&relay, &b, &c, 15).await;

    let friend_arrived = wait_until(15, async || {
        c.store().load_friends(Some("accepted")).unwrap_or_default().iter().any(|row| row.0 == f_master)
    })
    .await;
    assert!(friend_arrived, "C must learn B's friend over the Olm lane");
    let emote_arrived = wait_until(10, async || {
        c.store().list_personal_emote_entries().unwrap_or_default().iter().any(|row| row.0 == "canaryemote")
    })
    .await;
    assert!(emote_arrived, "C must learn B's personal emote row over the Olm lane");

    drain_events(&mut c);
    let server_id = create_server_and_wait(&mut b, "Sibling Lane Server").await;
    let joined = wait_event(&mut c, std::time::Duration::from_secs(12), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(joined, "C must onboard the server B announced over the Olm lane");

    drain_events(&mut c);
    c.cmd_tx
        .send(NodeCommand::RequestStateSync { source_device_id: b.device_id.clone() })
        .await
        .unwrap();
    let refreshed = wait_event(&mut c, std::time::Duration::from_secs(10), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(refreshed, "the manual state sync answers over the Olm lane");

    let tap = relay.wiretap();
    assert_eq!(tap.lane_leaks(), Vec::<String>::new(), "an Olm-only message reached the relay in the clear");
    for canary in ["canary-read-mid", "canaryemote"] {
        assert_eq!(tap.readable(canary), Vec::<String>::new(), "the relay read {canary}");
    }
}

/// A29. A sibling-lane row stamped far ahead of the frame that carried it outranked
/// every later write: a tombstone took a name for good, a read marker marked every
/// future message read, and a friendship stamp shielded a friend from that friend's
/// own removal. Such a row is refused (emotes) or held to the frame's time.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn authz_a_sibling_lane_stamp_never_runs_ahead_of_its_frame() {
    use super::types::{FriendListEntry, HavenMessage, PersonalEmoteEntry};

    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    const M_MASTER: u8 = 65;
    const B_DEV: u8 = 66;
    const C_DEV: u8 = 67;
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    let friend = NativeKeypair::from_secret_bytes(&seed_bytes(68)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev.clone(), c_dev.clone()]);

    let hash = "d".repeat(64);
    let mut b = spawn_node_with_friends(&relay, M_MASTER, B_DEV, &[]).await;
    b.store().merge_personal_emote_entry("keepme", &hash, false, "upload", 10).unwrap();
    let inbox = format!("inbox:{m_master}");
    assert!(wait_until(10, async || relay.room_devices(&inbox).contains(&b.device_id)).await, "B is up before C keys it");
    let c = spawn_node_with_friends(&relay, M_MASTER, C_DEV, &[]).await;
    expect_siblings_ready(&relay, &b, &c, 15).await;
    drain_events(&mut b);

    let now = super::frame_auth::now_ms();
    let far = now + 365 * 24 * 3600 * 1000;
    let ceiling = super::frame_auth::now_ms() + super::frame_auth::LIVE_SKEW_MS + 10_000;
    let emote = |name: &str, hash: &str, added_at: i64| PersonalEmoteEntry {
        name: name.into(), hash: hash.into(), animated: false, source: "upload".into(), added_at,
    };
    carry_as(&c, &b, HavenMessage::PersonalEmoteSync {
        emotes: vec![emote("keepme", "", far), emote("newone", &hash, now)],
    })
    .await;
    assert!(
        wait_event(&mut b, std::time::Duration::from_secs(10), |ev| matches!(ev, NetworkEvent::PersonalEmotesUpdated)).await,
        "the sibling's ordinary row lands"
    );
    let names: Vec<String> = b.store().list_personal_emotes().unwrap().into_iter().map(|r| r.0).collect();
    assert!(names.contains(&"newone".to_string()), "the ordinary row landed, got {names:?}");
    assert!(names.contains(&"keepme".to_string()), "a far-future tombstone took the name, got {names:?}");

    carry_as(&c, &b, HavenMessage::ReadMarkers {
        markers: vec![
            ReadMarker { key: "dm:far".into(), message_id: String::new(), ts: far },
            ReadMarker { key: "dm:near".into(), message_id: String::new(), ts: now - 1_000 },
        ],
    })
    .await;
    let mut got: Vec<ReadMarker> = Vec::new();
    assert!(
        wait_event(&mut b, std::time::Duration::from_secs(10), |ev| match ev {
            NetworkEvent::ReadMarkersReceived { markers } => {
                got = markers.clone();
                true
            }
            _ => false,
        })
        .await,
        "the markers reach the store"
    );
    let ts_of = |key: &str| got.iter().find(|m| m.key == key).map(|m| m.ts);
    assert_eq!(ts_of("dm:near"), Some(now - 1_000), "an ordinary marker moved");
    assert!(ts_of("dm:far").is_some_and(|ts| ts <= ceiling), "a far-future marker ran ahead: {:?}", ts_of("dm:far"));

    carry_as(&c, &b, HavenMessage::FriendListSync {
        friends: vec![FriendListEntry { peer_id: friend.clone(), status: "accepted".into(), direction: String::new(), requested_at: far }],
        removed: Vec::new(),
    })
    .await;
    assert!(
        wait_event(&mut b, std::time::Duration::from_secs(10), |ev| matches!(ev, NetworkEvent::FriendsBackfilled { .. })).await,
        "the sibling's friend lands"
    );
    let since = b.store().get_friend_row(&friend).unwrap().map(|row| row.2);
    assert!(since.is_some_and(|s| s <= ceiling), "a far-future friendship stamp landed: {since:?}");
}

/// The first frame `from` sent whose body is `kind` and contains `marker`.
fn recorded_frame(relay: &MockRelay, from: &str, kind: &str, marker: &str) -> Vec<u8> {
    relay
        .recorded_frames(from)
        .into_iter()
        .find(|data| {
            let body = super::frame_auth::unchecked_body(data);
            let named = serde_json::from_slice::<serde_json::Value>(body)
                .is_ok_and(|v| v.get("type").and_then(|t| t.as_str()) == Some(kind));
            named && body.windows(marker.len()).any(|w| w == marker.as_bytes())
        })
        .unwrap_or_else(|| panic!("{from} never sent a {kind} frame holding {marker}"))
}

/// A29 (B11 variants). A public channel's frames are plaintext and wait in the
/// relay's ring, so the relay can hand an old one back at will: an old unreaction
/// took away a later re-add, and an old card replaced a newer one.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn authz_a_replayed_public_unreaction_or_card_never_undoes_a_later_one() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    const O_MASTER: u8 = 115;
    const J_MASTER: u8 = 125;
    let o_master = NativeKeypair::from_secret_bytes(&seed_bytes(O_MASTER)).peer_id();
    let j_master = NativeKeypair::from_secret_bytes(&seed_bytes(J_MASTER)).peer_id();
    let mut o = spawn_node_with_friends(&relay, O_MASTER, O_MASTER, &[&j_master]).await;
    let dm_room = super::types::dm_room_code(&o_master, &j_master);
    assert!(wait_until(10, async || relay.room_devices(&dm_room).contains(&o.device_id)).await, "O is up before J keys it");
    let mut j = spawn_node_with_friends(&relay, J_MASTER, J_MASTER, &[&o_master]).await;
    expect_dm_pair_ready(&relay, &o, &j, 15).await;

    let server_id = create_server_and_wait(&mut o, "Public Replay Server").await;
    let general = general_channel_of(&server_id);
    j.cmd_tx
        .send(NodeCommand::JoinServer { server_id: server_id.clone(), twitch_proof_json: None, nsfw_confirmed: false, owner_pin: None, join_key: invite_key(&server_id) })
        .await
        .unwrap();
    assert!(
        wait_event(&mut j, std::time::Duration::from_secs(8), |ev| {
            matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
        })
        .await,
        "the member joins"
    );
    expect_mls_group(&[&o, &j], &server_id, 15).await;
    o.cmd_tx
        .send(NodeCommand::SetChannelPublic { server_id: server_id.clone(), channel_id: general.clone(), is_public: true })
        .await
        .unwrap();
    assert!(
        wait_until(10, async || j.server_state(&server_id).is_some_and(|s| s.is_channel_public(&general))).await,
        "the member knows #general is public"
    );

    const MID: &str = "pub-replay-1";
    drain_events(&mut j);
    o.cmd_tx
        .send(NodeCommand::SendChannelMessage {
            server_id: server_id.clone(),
            channel_id: general.clone(),
            text: "see https://example.com/replay".to_string(),
            message_id: MID.to_string(),
            reply_to_mid: None,
            link_preview: None,
        })
        .await
        .unwrap();
    assert!(
        wait_event(&mut j, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::ChannelMessageReceived { message_id, .. } if message_id == MID)
        })
        .await,
        "the member gets the post"
    );
    relay.set_recording(&o.device_id, true);
    relay.set_recording(&j.device_id, true);

    // J reacts, takes it back and reacts again; the relay replays the take-back.
    let react = |add: bool| {
        let (server_id, channel_id) = (server_id.clone(), general.clone());
        let (message_id, emoji) = (MID.to_string(), "👍".to_string());
        if add {
            NodeCommand::AddChannelReaction { server_id, channel_id, message_id, emoji }
        } else {
            NodeCommand::RemoveChannelReaction { server_id, channel_id, message_id, emoji }
        }
    };
    for add in [true, false, true] {
        drain_events(&mut o);
        j.cmd_tx.send(react(add)).await.unwrap();
        assert!(
            wait_event(&mut o, std::time::Duration::from_secs(10), |ev| match ev {
                NetworkEvent::ChannelReactionAdded { message_id, .. } => add && message_id == MID,
                NetworkEvent::ChannelReactionRemoved { message_id, .. } => !add && message_id == MID,
                _ => false,
            })
            .await,
            "the owner sees the reaction change (add = {add})"
        );
    }
    let unreact = recorded_frame(&relay, &j.device_id, "pub_ch_unreact", MID);
    relay.inject(&server_id, &j.device_id, &o.device_id, unreact);
    let removed = seen_before_flush(&relay, &mut o, |ev| matches!(ev, NetworkEvent::ChannelReactionRemoved { .. })).await;
    assert!(!removed, "a replayed unreaction was shown as removing the re-add");
    let held = o.store().load_reactions_for_messages(&[MID.to_string()]).unwrap_or_default();
    assert!(
        held.get(MID).is_some_and(|r| r.iter().any(|(emoji, reactor, _)| emoji == "👍" && *reactor == j_master)),
        "a replayed unreaction removed the re-add: {held:?}"
    );

    // O sets card A, then card B over the same text; the relay replays A.
    let card = |title: &str| crate::node::LinkPreviewRef {
        url: "https://example.com/replay".to_string(),
        title: title.to_string(),
        description: String::new(),
        domain: "example.com".to_string(),
        site_name: String::new(),
        thumb_webp_b64: None,
        thumb_w: None,
        thumb_h: None,
        rich: None,
    };
    for title in ["replay-card-a", "replay-card-b"] {
        drain_events(&mut j);
        o.cmd_tx
            .send(NodeCommand::AttachChannelLinkPreview {
                server_id: server_id.clone(),
                channel_id: general.clone(),
                message_id: MID.to_string(),
                preview: Some(Box::new(card(title))),
            })
            .await
            .unwrap();
        assert!(
            wait_event(&mut j, std::time::Duration::from_secs(10), |ev| {
                matches!(ev, NetworkEvent::ChannelLinkPreviewUpdated { preview: Some(p), .. } if p.title == title)
            })
            .await,
            "the member gets {title}"
        );
    }
    let first_card = recorded_frame(&relay, &o.device_id, "pub_lp_set", "replay-card-a");
    relay.inject(&server_id, &o.device_id, &j.device_id, first_card);
    // Card B can arrive twice (public channel ops ride two transports), so only the
    // replayed card counts as a flip.
    let flipped = seen_before_flush(&relay, &mut j, |ev| {
        matches!(ev, NetworkEvent::ChannelLinkPreviewUpdated { preview: Some(p), .. } if p.title == "replay-card-a")
    })
    .await;
    let shown = j.store().get_channel_message_sig_row(MID).and_then(|r| r.link_preview).map(|c| c.title);
    assert!(!flipped && shown.as_deref() == Some("replay-card-b"), "a replayed older card replaced the newer one: {shown:?}");
}

/// HOL-SEC-056. A sibling's announce for a server we already hold used to run the
/// join flow again, and while that join was pending any member's snapshot could
/// replace our state. Now it only refreshes the list.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn authz_a_sibling_announce_for_a_held_server_starts_no_join() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    const M_MASTER: u8 = 65;
    const B_DEV: u8 = 66;
    const C_DEV: u8 = 67;
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev.clone(), c_dev.clone()]);

    let mut b = spawn_node_with_friends(&relay, M_MASTER, B_DEV, &[]).await;
    sleep_ms(1500).await;
    let mut c = spawn_node_with_friends(&relay, M_MASTER, C_DEV, &[]).await;
    expect_siblings_ready(&relay, &b, &c, 15).await;
    drain_events(&mut c);
    let server_id = create_server_and_wait(&mut b, "Held Server").await;
    let joined = wait_event(&mut c, std::time::Duration::from_secs(12), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(joined, "C onboards the new server from B's announce");

    relay.set_recording(&c.device_id, true);
    drain_events(&mut c);
    c.cmd_tx
        .send(NodeCommand::RequestStateSync { source_device_id: b.device_id.clone() })
        .await
        .unwrap();
    let refreshed = wait_event(&mut c, std::time::Duration::from_secs(10), |ev| {
        matches!(ev, NetworkEvent::ServerJoined { server_id: sid, .. } if *sid == server_id)
    })
    .await;
    assert!(refreshed, "the second announce still refreshes C's list");
    assert!(
        frames_of_type(&relay, &c.device_id, "join_sealed").is_empty(),
        "HOL-SEC-056: an announce for a server C holds started a join",
    );
    drop(b);
}

// ── Server ids name only servers (audit section 2, item 4) ──────────────

/// A server id is 32 or 40 lowercase hex: `S#chan` would alias the MLS subgroup of
/// (S, chan) and `conf:` a meeting, which no server state may hold. A join or a
/// sibling's announce naming either joins no room and leaves no row behind.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn join_with_a_malformed_server_id_starts_nothing() {
    use super::types::HavenMessage;
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    const M_MASTER: u8 = 68;
    const B_DEV: u8 = 69;
    const C_DEV: u8 = 70;
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev, c_dev]);
    let b = spawn_node_on(&relay, M_MASTER, B_DEV).await;
    let c = spawn_node_on(&relay, M_MASTER, C_DEV).await;
    seed_device_list_into_db(&b.db_path, &b.passphrase, M_MASTER, &[B_DEV, C_DEV]);
    seed_device_list_into_db(&c.db_path, &c.passphrase, M_MASTER, &[B_DEV, C_DEV]);
    expect_siblings_ready(&relay, &b, &c, 30).await;

    let sid = "ab".repeat(20);
    let bad = [format!("{sid}#s1-general"), format!("conf:{}", "cd".repeat(20))];
    let key = Some(fresh_reply_key());
    let join = |server_id: &str| NodeCommand::JoinServer {
        server_id: server_id.to_string(), twitch_proof_json: None, nsfw_confirmed: false, owner_pin: None, join_key: key.clone(),
    };
    let announce = |server_id: &str| HavenMessage::SiblingServerAnnounce {
        server_id: server_id.to_string(), owner: None, join_key: key.clone(),
    };
    for id in &bad {
        b.cmd_tx.send(join(id)).await.unwrap();
        carry_as(&b, &c, announce(id)).await;
    }
    // Commands and carried frames are handled in order: a well-formed id behind them.
    b.cmd_tx.send(join(&sid)).await.unwrap();
    carry_as(&b, &c, announce(&sid)).await;
    assert!(
        wait_until(10, async || {
            let in_room = relay.room_devices(&sid);
            in_room.contains(&b.device_id) && in_room.contains(&c.device_id)
        })
        .await,
        "a well-formed id starts both joins"
    );
    assert!(wait_until(10, async || b.pending_joins().iter().any(|(s, _, _)| *s == sid)).await, "B keeps a row for it");
    for id in &bad {
        assert!(relay.room_devices(id).is_empty(), "{id}: a malformed id joined a room");
        assert!(b.pending_joins().iter().all(|(s, _, _)| s != id), "{id}: a malformed id left a pending row");
        for node in [&b, &c] {
            assert!(node.live_server_state(id).await.is_none() && node.mls_epoch(id).await.is_none(), "{id}: state or group");
        }
    }
}

/// Claim C-24 on the receiving side: an Olm-only message that arrives in the clear
/// counts for nothing, even sealed by our own sibling, so a sender that regressed to
/// plaintext fails loudly instead of leaking quietly.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn c24_a_plaintext_copy_of_an_olm_only_message_is_dropped() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    const M_MASTER: u8 = 68;
    const B_DEV: u8 = 69;
    const C_DEV: u8 = 70;
    let m_master = NativeKeypair::from_secret_bytes(&seed_bytes(M_MASTER)).peer_id();
    let b_dev = NativeKeypair::from_secret_bytes(&seed_bytes(B_DEV)).peer_id();
    let c_dev = NativeKeypair::from_secret_bytes(&seed_bytes(C_DEV)).peer_id();
    let stranger = NativeKeypair::from_secret_bytes(&seed_bytes(71)).peer_id();
    super::resolver::seed_self(&m_master, &[b_dev.clone(), c_dev.clone()]);

    let b = spawn_node_with_friends(&relay, M_MASTER, B_DEV, &[]).await;
    sleep_ms(1500).await;
    let mut c = spawn_node_with_friends(&relay, M_MASTER, C_DEV, &[]).await;
    expect_siblings_ready(&relay, &b, &c, 15).await;

    let plain = super::types::HavenMessage::FriendListSync {
        friends: vec![super::types::FriendListEntry {
            peer_id: stranger.clone(),
            status: "accepted".into(),
            direction: "outgoing".into(),
            requested_at: 1,
        }],
        removed: Vec::new(),
    };
    relay.inject_direct(
        &format!("inbox:{m_master}"), &b.device_id, &c.device_id,
        serde_json::to_vec(&plain).unwrap(),
    );
    flush_frames(&relay, &mut c).await;
    assert_eq!(
        c.friend_status(&stranger), None,
        "a plaintext FriendListSync from our own sibling planted a friend",
    );
}

/// Claim C-24 for server traffic: op broadcasts, sync requests, typing, the post
/// hint, voice presence and state, status and the kick notice ride MLS or Olm; the
/// relay reads none of them in the clear.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn c24_server_traffic_rides_mls_or_olm() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    relay.start_wiretap();
    let (mut o, mut m, mut x, server_id) = three_member_server(&relay, 72, 73, 74).await;
    let general = general_channel_of(&server_id);

    o.cmd_tx
        .send(NodeCommand::CreateChannel {
            server_id: server_id.clone(),
            channel_id: crate::node::new_channel_id(&server_id),
            name: "Voice".to_string(),
            category: None,
            channel_type: "voice".to_string(),
        })
        .await
        .unwrap();
    let mut voice = None;
    let made = wait_event(&mut m, std::time::Duration::from_secs(10), |ev| match ev {
        NetworkEvent::ChannelAdded { channel_id, channel_type, .. } if channel_type == "voice" => {
            voice = Some(channel_id.clone());
            true
        }
        _ => false,
    })
    .await;
    assert!(made, "M learns the new channel from the op");
    let voice = voice.unwrap();

    m.cmd_tx
        .send(NodeCommand::SendTypingIndicator { server_id: server_id.clone(), channel_id: general.clone() })
        .await
        .unwrap();
    assert!(
        wait_event(&mut o, std::time::Duration::from_secs(10), |ev| matches!(ev, NetworkEvent::TypingStarted { .. })).await,
        "O sees M typing in the channel"
    );
    o.cmd_tx
        .send(NodeCommand::SendTypingIndicator { server_id: String::new(), channel_id: m.master_id.clone() })
        .await
        .unwrap();
    assert!(
        wait_event(&mut m, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::TypingStarted { server_id, .. } if server_id.is_empty())
        })
        .await,
        "M sees O typing in their DM"
    );

    m.cmd_tx
        .send(NodeCommand::SendChannelMessage {
            server_id: server_id.clone(),
            channel_id: general.clone(),
            text: "a post".to_string(),
            message_id: "c24-post".to_string(),
            reply_to_mid: None,
            link_preview: None,
        })
        .await
        .unwrap();
    assert!(
        wait_event(&mut x, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::ChannelNotificationHint { message_id, .. } if message_id == "c24-post")
        })
        .await,
        "X gets the post's hint"
    );

    m.cmd_tx
        .send(NodeCommand::VoiceChannelJoin { server_id: server_id.clone(), channel_id: voice.clone() })
        .await
        .unwrap();
    assert!(
        wait_event(&mut o, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::VoiceChannelJoined { channel_id, .. } if *channel_id == voice)
        })
        .await,
        "O sees M join the voice channel"
    );
    m.cmd_tx
        .send(NodeCommand::VoiceChannelSendSignal {
            server_id: server_id.clone(),
            channel_id: voice.clone(),
            peer_id: o.master_id.clone(),
            signal_type: "audio_state".to_string(),
            payload: serde_json::json!({ "call_id": voice, "muted": true, "deafened": false }).to_string(),
        })
        .await
        .unwrap();
    assert!(
        wait_event(&mut o, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::VoiceChannelSignal { signal_type, .. } if signal_type == "audio_state")
        })
        .await,
        "O sees M mute"
    );

    x.cmd_tx.send(NodeCommand::SetInvisible { invisible: true }).await.unwrap();
    assert!(
        wait_event(&mut o, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::PeerStatusChanged { status, .. } if status == "invisible")
        })
        .await,
        "O hears X go invisible"
    );

    o.cmd_tx
        .send(NodeCommand::KickMember { server_id: server_id.clone(), peer_id: x.master_id.clone() })
        .await
        .unwrap();
    let x_sid = server_id.clone();
    assert!(
        wait_until(15, async || x.live_server_state(&x_sid).await.is_none()).await,
        "X hears the kick"
    );

    assert_eq!(relay.wiretap().lane_leaks(), Vec::<String>::new(), "an Olm-only message reached the relay in the clear");
}

/// J9: a post's hint in a restricted channel rides that channel's subgroup, so the
/// qualifying member hears it, the relay reads nothing of it, and a member who
/// cannot see the channel cannot even decrypt it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
#[allow(clippy::await_holding_lock)] // serializes harness tests vs the global resolver
async fn c24_a_restricted_channel_hint_rides_its_subgroup() {
    let _g = test_guard();
    let global_tmp = crate::test_tmp::tempdir().expect("global tmp");
    unsafe { std::env::set_var("HOLLOW_DATA_DIR", global_tmp.path()); }

    let relay = MockRelay::new();
    relay.start_wiretap();
    let (mut o, mut m, mut x, server_id) = three_member_server(&relay, 75, 76, 77).await;
    expect_mls_group(&[&o, &m, &x], &server_id, 20).await;

    o.cmd_tx
        .send(NodeCommand::CreateChannel {
            server_id: server_id.clone(),
            channel_id: crate::node::new_channel_id(&server_id),
            name: "staff".to_string(),
            category: None,
            channel_type: "text".to_string(),
        })
        .await
        .unwrap();
    let mut staff = None;
    assert!(
        wait_event(&mut o, std::time::Duration::from_secs(5), |ev| match ev {
            NetworkEvent::ChannelAdded { channel_id, name, .. } if name == "staff" => {
                staff = Some(channel_id.clone());
                true
            }
            _ => false,
        })
        .await,
        "O creates the channel"
    );
    let staff = staff.unwrap();
    o.cmd_tx
        .send(NodeCommand::ChangeRole { server_id: server_id.clone(), peer_id: m.master_id.clone(), new_role: "admin".to_string() })
        .await
        .unwrap();
    assert!(
        wait_until(10, async || m.live_role(&server_id, &m.master_id).await == crate::crdt::operations::MemberRole::Admin).await,
        "M is promoted"
    );
    o.cmd_tx
        .send(NodeCommand::SetChannelVisibility {
            server_id: server_id.clone(),
            channel_id: staff.clone(),
            visibility: "admin".to_string(),
        })
        .await
        .unwrap();
    let subgroup = crate::crypto::subgroup_id(&server_id, &staff);
    expect_mls_leaf(&o, &subgroup, &m.device_id, 25).await;

    drain_events(&mut m);
    drain_events(&mut x);
    o.cmd_tx
        .send(NodeCommand::SendChannelMessage {
            server_id: server_id.clone(),
            channel_id: staff.clone(),
            text: "for staff".to_string(),
            message_id: "staff-post".to_string(),
            reply_to_mid: None,
            link_preview: None,
        })
        .await
        .unwrap();
    assert!(
        wait_event(&mut m, std::time::Duration::from_secs(10), |ev| {
            matches!(ev, NetworkEvent::ChannelNotificationHint { message_id, .. } if message_id == "staff-post")
        })
        .await,
        "the qualifying member hears the hint through the subgroup"
    );
    assert!(
        !wait_event(&mut x, std::time::Duration::from_millis(1500), |ev| {
            matches!(ev, NetworkEvent::ChannelNotificationHint { message_id, .. } if message_id == "staff-post")
        })
        .await,
        "a member who cannot see the channel hears nothing of it"
    );
    let tap = relay.wiretap();
    assert_eq!(tap.lane_leaks(), Vec::<String>::new(), "an Olm-only message reached the relay in the clear");
    assert_eq!(tap.readable("staff-post"), Vec::<String>::new(), "the relay read the restricted post's hint");
}

